window.I18N_LOCALES = window.I18N_LOCALES || {};
window.I18N_LOCALES["ru"] = {"_label":"Русский","tool.apy-calc.name":"Калькулятор APY","tool.apy-calc.use":"Переведите APR в APY (или APY обратно в APR) для любой периодичности начисления процентов, посмотрите, как растёт вклад, и сравните одну и ту же ставку при годовом, месячном, дневном или непрерывном начислении.","tool.apy-calc.desc":"Переведите APR в APY (или APY в APR) для любой периодичности начисления процентов, сравните ставки и посмотрите рост вклада. Бесплатно, расчёт в вашем браузере.","tool.blood-pressure-checker.name":"Проверка артериального давления","tool.blood-pressure-checker.use":"Введите систолическое и диастолическое давление, чтобы мгновенно узнать свою категорию по ACC/AHA.","tool.blood-pressure-checker.desc":"Введите систолическое и диастолическое давление, чтобы мгновенно узнать свою категорию по ACC/AHA — норма, повышенное, стадия 1, стадия 2 или криз — с полной справочной таблицей. Бесплатно, все вычисления в вашем браузере.","tool.box-shadow-generator.name":"Генератор Box Shadow","tool.box-shadow-generator.use":"Двигайте ползунки, чтобы задать смещение, размытие, растяжение и цвет, накладывайте несколько слоёв тени и мгновенно копируйте готовый CSS box-shadow.","tool.box-shadow-generator.desc":"Настройте смещение, размытие, растяжение, цвет и прозрачность ползунками, наложите до 4 слоёв тени в живом предпросмотре и скопируйте готовый CSS box-shadow. Всё в вашем браузере.","tool.break-even-calc.name":"Калькулятор точки безубыточности","tool.break-even-calc.use":"Затраты побеждают ровно до одного объёма продаж. Введите три числа и найдите его.","tool.break-even-calc.desc":"Введите постоянные затраты, цену и переменные затраты на единицу, чтобы узнать точку безубыточности в единицах, выручку и маржинальную прибыль — плюс необязательный расчёт целевой прибыли и таблицу чувствительности к цене.","tool.calorie-deficit-calc.name":"Калькулятор дефицита калорий","tool.calorie-deficit-calc.use":"Сколько калорий есть, чтобы похудеть? Введите свои данные и темп похудения в неделю, чтобы получить дневную норму калорий и примерный срок достижения целевого веса.","tool.calorie-deficit-calc.desc":"Введите свои данные и желаемый темп похудения в неделю, чтобы получить дневную норму калорий с дефицитом и примерный срок достижения целевого веса. Бесплатно, без рекламы, расчёт в браузере.","tool.circle-calc.name":"Калькулятор круга","tool.circle-calc.use":"Введите радиус, диаметр, длину окружности или площадь любого круга — остальные три значения заполнятся мгновенно, а нужная формула будет показана ниже.","tool.circle-calc.desc":"Введите радиус, диаметр, длину окружности или площадь круга и мгновенно получите остальные три значения с указанием формулы. Бесплатно, считается в браузере.","tool.credit-card-interest-calc.name":"Калькулятор процентов по кредитной карте","tool.credit-card-interest-calc.use":"Введите баланс и годовую ставку (APR), чтобы точно увидеть, сколько процентов вы платите прямо сейчас. Затем запустите симулятор ловушки минимального платежа и сравните, сколько лет и сколько процентов уйдёт при оплате только минимума и при фиксированном платеже.","tool.credit-card-interest-calc.desc":"Введите баланс и годовую ставку (APR), чтобы сразу увидеть, сколько процентов набегает сегодня; затем смоделируйте ловушку минимального платежа: сравните годы и сумму процентов при минимальном и фиксированном платеже. Бесплатно, всё в браузере.","tool.debt-payoff-calc.name":"Калькулятор погашения долга","tool.debt-payoff-calc.use":"Два порядка погашения, один бюджет. Посмотрите, что закроет долги быстрее и сколько стоит разница.","tool.debt-payoff-calc.desc":"Введите остаток долга, годовую ставку и платёж, чтобы узнать число месяцев до полного погашения, общую сумму процентов, дату закрытия долга и полный график платежей. Бесплатно, всё считается локально в браузере.","tool.electricity-cost-calc.name":"Калькулятор стоимости электроэнергии","tool.electricity-cost-calc.use":"Ватты умножить на часы, разделить на 1000 и умножить на тариф. Смотрите, сколько каждый прибор добавляет к счёту.","tool.electricity-cost-calc.desc":"Введите мощность прибора, цену за кВт·ч и часы использования, чтобы узнать стоимость за день, месяц и год. Быстро добавляйте приборы через пресеты — холодильник, кондиционер и другие.","tool.fire-calc.name":"Калькулятор FIRE","tool.fire-calc.use":"Превратите годовые расходы в число FIRE по правилу 4% (или любой ставке изъятия от 3% до 5%), затем узнайте, сколько лет накоплений и инвестиций отделяет вас от финансовой независимости — плюс сравнение Lean/Regular/Fat FIRE. Работает с любой валютой.","tool.fire-calc.desc":"Превратите годовые расходы в число FIRE по правилу 4%, узнайте годы до финансовой независимости и целевую дату, плюс уровни Lean/Regular/Fat. Бесплатно, в браузере.","tool.margin-calc.name":"Калькулятор маржи","tool.margin-calc.use":"Маржа — это прибыль, делённая на цену; наценка — прибыль, делённая на себестоимость. Маржа 40% равна наценке 66,7%.","tool.margin-calc.desc":"Введите любые две величины из себестоимости, выручки, маржи % или наценки %, чтобы мгновенно получить остальное, увидеть прибыль и разобраться в вечной путанице между маржой и наценкой.","tool.markup-calc.name":"Калькулятор наценки","tool.markup-calc.use":"Превратите себестоимость в цену продажи или узнайте наценку и маржу по цене, которую вы уже назначили, — мгновенно, прямо в браузере.","tool.markup-calc.desc":"Введите себестоимость и наценку %, чтобы получить цену продажи и прибыль, либо себестоимость и цену — чтобы найти наценку % и маржу. Бесплатно, мгновенно, в браузере.","tool.meta-tag-generator.name":"Генератор мета-тегов","tool.meta-tag-generator.use":"Заполните данные страницы и получите готовые к вставке теги <title>, meta description, Open Graph и Twitter Card — с живым предпросмотром поиска и соцсетей.","tool.meta-tag-generator.desc":"Создавайте теги title, description, canonical, robots, Open Graph и Twitter Card в одной форме с живым предпросмотром поиска Google и соцсетей.","tool.pythagorean-calc.name":"Калькулятор теоремы Пифагора","tool.pythagorean-calc.use":"Введите любые две стороны — катет a, катет b или гипотенузу c — и третья появится мгновенно, вместе с шагами решения, площадью и периметром.","tool.pythagorean-calc.desc":"Введите любые две стороны прямоугольного треугольника и мгновенно найдите третью по формуле a² + b² = c², с шагами решения, площадью и периметром. Бесплатно, прямо в браузере.","tool.ratio-calc.name":"Калькулятор пропорций","tool.ratio-calc.use":"Решите пропорцию, упростите отношение до наименьших членов или измените его масштаб — выберите вкладку, введите числа и мгновенно получите ответ.","tool.ratio-calc.desc":"Найдите неизвестное значение в A:B = C:D, упростите отношение до наименьших членов или масштабируйте отношение на коэффициент. Бесплатно, мгновенно, все расчёты в браузере.","tool.retirement-calc.name":"Пенсионный калькулятор","tool.retirement-calc.use":"Узнайте, сколько будет на вашем 401(k) к пенсии и какую часть внёс работодатель.","tool.retirement-calc.desc":"Укажите возраст, накопления и ежемесячный взнос, чтобы спрогнозировать пенсионный капитал и безопасный месячный доход по правилу 4%, с графиком роста по годам. Бесплатно, в браузере.","tool.slope-calc.name":"Калькулятор уклона","tool.slope-calc.use":"Введите две точки (x₁, y₁) и (x₂, y₂), чтобы мгновенно получить уклон, уравнение прямой, угол наклона, процент уклона, расстояние и середину отрезка — прямо в браузере.","tool.slope-calc.desc":"Введите две точки и мгновенно получите уклон, уравнение y=mx+b, угол наклона, процент уклона, расстояние и середину отрезка. Бесплатно, в браузере.","tool.steps-to-miles-calc.name":"Калькулятор шагов в мили","tool.steps-to-miles-calc.use":"Сколько вы на самом деле прошли? Введите количество шагов и рост (или измеренную длину шага), чтобы увидеть расстояние в милях и километрах, время ходьбы и приблизительную оценку сожжённых калорий.","tool.steps-to-miles-calc.desc":"Введите количество шагов и рост (или длину шага), чтобы получить расстояние в милях и км, а также время ходьбы и приблизительно сожжённые калории — бесплатно, всё считается в браузере.","tool.timesheet-calc.name":"Калькулятор Табеля Учёта Времени","tool.timesheet-calc.use":"Указывайте время начала, окончания и неоплачиваемого перерыва для каждого дня недели — получайте часы за день и за неделю в десятичном формате и чч:мм, а также зарплату с автоматической надбавкой 1,5× за сверхурочные — прямо в браузере.","tool.timesheet-calc.desc":"Введите время начала, окончания и перерыва за каждый день, чтобы получить часы за неделю (десятичные и чч:мм) и зарплату с оплатой сверхурочных 1.5x после 40 часов. Бесплатно, расчёт в браузере.","tool.upside-down-text.name":"Генератор перевёрнутого текста","tool.upside-down-text.use":"Введите или вставьте любой текст и мгновенно переверните его вверх ногами, отразите как в зеркале или превратите в капитель — бесплатно, копирование в один клик, прямо в вашем браузере.","tool.upside-down-text.desc":"Переверните любой текст вверх ногами, отразите его как в зеркале или превратите в капитель с помощью похожих символов Юникода — бесплатно, мгновенно и полностью в вашем браузере.","tool.angle-conv.name":"Конвертер углов","tool.angle-conv.use":"Введите угол один раз — и сразу увидите его в градусах, радианах, градах и оборотах, с точными дробями π для типичных углов.","tool.angle-conv.desc":"Мгновенно переводите градусы, радианы, грады и обороты, с точными дробями π для типичных углов, таблицей единичной окружности и режимом градусы-минуты-секунды (ГМС).","tool.blood-sugar-conv.name":"Конвертер сахара в крови","tool.blood-sugar-conv.use":"Введите mg/dL или mmol/L в любое поле — другое значение и ваш референсный диапазон появятся мгновенно.","tool.blood-sugar-conv.desc":"Мгновенно конвертируйте сахар в крови между mg/dL и mmol/L в обе стороны, с референсными диапазонами натощак и после еды — всё в браузере.","tool.chmod-calc.name":"Калькулятор Chmod","tool.chmod-calc.use":"Включайте чтение, запись и выполнение для владельца, группы и остальных — восьмеричный код, символьная запись и команда chmod обновляются мгновенно.","tool.chmod-calc.desc":"Мгновенно конвертирует права доступа между чекбоксами, восьмеричным (755) и символьным (rwxr-xr-x) форматом, с поддержкой setuid/setgid/sticky bit.","tool.css-minifier.name":"Минификатор CSS","tool.css-minifier.use":"Вставьте свой CSS и минифицируйте его — удаление комментариев, схлопывание пробелов, сокращение hex-цветов, безопасное удаление единиц у нулевых значений — либо отформатируйте уже минифицированный CSS обратно в читаемый вид с отступами. Мгновенно увидите сэкономленный размер.","tool.css-minifier.desc":"Минифицируйте CSS, удаляя комментарии, схлопывая пробелы, сокращая hex-цвета и убирая единицы у нулевых значений — либо отформатируйте его обратно в читаемый код с отступами. Всё в вашем браузере.","tool.energy-conv.name":"Конвертер энергии","tool.energy-conv.use":"Введите значение энергии один раз — и сразу увидите его в джоулях, калориях, кВт·ч, БТЕ и других единицах, включая перевод кДж в калории.","tool.energy-conv.desc":"Мгновенно переводите джоули, кДж, калории, ккал, Вт·ч, кВт·ч, БТЕ и фут-фунты — с объяснением перевода кДж в калории и ловушки пищевой калории.","tool.find-replace-text.name":"Найти и заменить","tool.find-replace-text.use":"Замените сразу все совпадения в тексте. Введите, что искать и на что заменить, посмотрите подсвеченный предпросмотр совпадений и примените изменения.","tool.find-replace-text.desc":"Ищите и заменяйте текст с учётом регистра, целых слов и регулярных выражений, с живым предпросмотром перед применением.","tool.fuel-economy-conv.name":"Конвертер расхода топлива","tool.fuel-economy-conv.use":"Введите значение расхода топлива в MPG (США), MPG (Великобритания), л/100км или км/л — остальные поля обновятся мгновенно. Учтите: л/100км работает наоборот, здесь меньше — лучше.","tool.fuel-economy-conv.desc":"Мгновенно переводите расход топлива между MPG (США), MPG (Великобритания), л/100км и км/л — вводите в любое поле, остальное обновится само. Включает таблицу частых значений, всё считается в браузере.","tool.gcf-lcm-calc.name":"Калькулятор НОД и НОК","tool.gcf-lcm-calc.use":"Введите от 2 до 10 целых чисел, чтобы найти их наибольший общий делитель и наименьшее общее кратное — с разложением на простые множители и шагами алгоритма Евклида для каждого расчёта.","tool.gcf-lcm-calc.desc":"Вычислите НОД и НОК от 2 до 6 целых чисел с разложением на простые множители и пошаговым алгоритмом Евклида для каждого расчёта. Бесплатно, работает прямо в браузере.","tool.leap-year-checker.name":"Калькулятор високосного года","tool.leap-year-checker.use":"Введите год, чтобы сразу узнать, високосный ли он, с объяснением правила деления на 4/100/400; также узнайте високосные годы в любом диапазоне и следующий или предыдущий високосный год от сегодняшнего дня.","tool.leap-year-checker.desc":"Проверьте, является ли год високосным, узнайте правило деления на 4/100/400, получите список високосных лет в диапазоне и найдите следующий или предыдущий.","tool.military-time-conv.name":"Конвертер военного времени","tool.military-time-conv.use":"Введите время практически в любом формате — 0930, 21:45 или 9:45 PM — и мгновенно получите военное или стандартное время, а также узнайте, как его произнести.","tool.military-time-conv.desc":"Конвертируйте военное (24-часовое) время в стандартное 12-часовое время AM/PM и обратно, с гибким разбором ввода и полной справочной таблицей на 24 часа. Все вычисления выполняются в вашем браузере.","tool.power-conv.name":"Конвертер мощности","tool.power-conv.use":"Введите число один раз — мгновенно увидите его в каждой единице мощности.","tool.power-conv.desc":"Мгновенно переводите мощность между ваттами, киловаттами, мегаваттами, лошадиными силами (hp и PS), БТЕ/ч и фунто-футами в секунду — всё в браузере.","tool.pressure-conv.name":"Конвертер давления","tool.pressure-conv.use":"Введите число один раз — и сразу увидите его во всех 10 единицах давления.","tool.pressure-conv.desc":"Мгновенно переводите давление между Pa, kPa, MPa, bar, psi, atm, mmHg и inHg — все 8 единиц обновляются по мере ввода, прямо в браузере.","tool.protein-intake-calc.name":"Калькулятор потребления белка","tool.protein-intake-calc.use":"Сколько белка нужно есть каждый день? Введите свой вес и выберите уровень активности или цель — получите суточный диапазон белка в граммах, разбивку по приёмам пищи и простые пищевые эквиваленты: куриная грудка, яйца и тофу.","tool.protein-intake-calc.desc":"Введите вес и уровень активности или цель, чтобы получить суточный диапазон белка в граммах, разбивку по приёмам пищи и пищевые эквиваленты. Бесплатно, без рекламы, расчёт в браузере.","tool.quadratic-solver.name":"Решение квадратных уравнений","tool.quadratic-solver.use":"Введите коэффициенты a, b и c, чтобы решить ax² + bx + c = 0 — мгновенно получите корни, дискриминант, пошаговую подстановку и вершину параболы.","tool.quadratic-solver.desc":"Введите a, b и c, чтобы мгновенно решить любое квадратное уравнение: действительные, кратные или комплексные корни, дискриминант, пошаговую подстановку и вершину параболы. Бесплатно, прямо в браузере.","tool.random-team-gen.name":"Генератор случайных команд","tool.random-team-gen.use":"Вставьте список, выберите количество команд (или размер каждой) и получите честное, по-настоящему случайное распределение в один клик.","tool.random-team-gen.desc":"Вставьте имена и разделите их на честные команды по количеству или размеру с помощью криптографически случайного перемешивания. Остаток распределяется поровну. Перемешивайте заново в любой момент — бесплатно, прямо в браузере.","tool.random-word-gen.name":"Генератор случайных слов","tool.random-word-gen.use":"Нужно случайное слово? Выберите категорию — существительное, глагол или прилагательное, — добавьте необязательные фильтры и получите мгновенный список для Pictionary, идей для письма или любой словесной игры.","tool.random-word-gen.desc":"Генерируйте случайные английские слова с фильтром по существительному, глаголу или прилагательному, а также по начальной букве и длине. Отлично подходит для Pictionary, мозгового штурма и словесных игр — бесплатно, расчёт в браузере.","tool.subnet-calc.name":"Калькулятор подсетей IP","tool.subnet-calc.use":"Какая у меня подсеть? Введите IPv4-адрес и префикс CIDR (или маску подсети) — сеть, широковещательный адрес и диапазон доступных хостов появятся мгновенно.","tool.subnet-calc.desc":"Введите IPv4-адрес и префикс CIDR или маску подсети — мгновенно получите адрес сети, широковещательный адрес, диапазон доступных хостов и двоичное представление, всё в вашем браузере.","tool.week-number-check.name":"Номер недели сегодня","tool.week-number-check.use":"Какая сейчас неделя? Узнайте номер текущей недели по ISO 8601 сразу при загрузке страницы, проверьте неделю для любой даты или просмотрите диапазоны недель с понедельника по воскресенье за весь год.","tool.week-number-check.desc":"Мгновенно узнайте сегодняшний номер недели по ISO 8601, найдите неделю для любой даты и просмотрите диапазоны недель за весь год — все вычисления выполняются в вашем браузере.","tool.whitespace-remover.name":"Удаление Лишних Пробелов","tool.whitespace-remover.use":"Вставьте текст, чтобы мгновенно схлопнуть повторяющиеся пробелы, очистить пробелы в начале и конце каждой строки, убрать табуляцию, удалить пустые строки или стереть любые пробельные символы — включая скрытые неразрывные и нулевой ширины пробелы.","tool.whitespace-remover.desc":"Вставьте текст, чтобы схлопнуть двойные пробелы, обрезать края строк, убрать табуляцию, удалить пустые строки или стереть все пробелы — включая скрытые неразрывные и нулевой ширины, прямо в браузере.","tool.xml-formatter.name":"Форматировщик XML","tool.xml-formatter.use":"Вставьте XML, чтобы мгновенно отформатировать, проверить или минифицировать его — с сохранением CDATA, комментариев и декларации XML, а также точной строкой любой ошибки. Ничего не покидает ваш браузер.","tool.xml-formatter.desc":"Вставьте XML, чтобы отформатировать его с отступом в 2/4 пробела или табуляцию, минифицировать в одну строку, либо проверить и увидеть точную строку ошибки — прямо в браузере, с сохранением CDATA и комментариев.","tool.alarm-clock.name":"Онлайн-будильник","tool.alarm-clock.use":"Установите один или несколько будильников — быстрые пресеты вроде +5 минут или точное время подъёма — и этот бесплатный онлайн-будильник зазвонит со звуком и необязательным уведомлением. Без установки, без аккаунта, всё работает прямо в этой вкладке браузера.","tool.alarm-clock.desc":"Установите точное время будильника или быстрый пресет +5/+10/+30 минут, следите за живыми часами и получайте звук плюс уведомление при срабатывании. Храните до 5 будильников — всё в браузере, без установки.","tool.cat-age-calc.name":"Калькулятор возраста кошки","tool.cat-age-calc.use":"Сколько лет вашей кошке по-человечески? Введите возраст кошки (или посчитайте в обратную сторону от человеческого возраста), чтобы мгновенно получить перевод по ветеринарной формуле и узнать стадию жизни — от котёнка до пожилой кошки.","tool.cat-age-calc.desc":"Переведите возраст кошки в человеческие годы по ступенчатой ветеринарной формуле, узнайте стадию жизни, есть обратный режим. Бесплатно, прямо в браузере.","tool.date-add-calc.name":"Калькулятор дат","tool.date-add-calc.use":"Выберите начальную дату, прибавьте или вычтите дни, недели, месяцы или годы — и мгновенно увидите итоговую дату и день недели.","tool.date-add-calc.desc":"Прибавляйте или вычитайте дни, недели, месяцы или годы к дате и смотрите результат с днём недели. Необязательный режим рабочих дней пропускает выходные.","tool.hourly-to-salary-calc.name":"Калькулятор почасовой ставки в оклад","tool.hourly-to-salary-calc.use":"Введите почасовую ставку или годовой оклад — мгновенно увидите недельные, месячные и годовые суммы, направление можно менять в любой момент.","tool.hourly-to-salary-calc.desc":"Переведите почасовую ставку в недельную, месячную и годовую оплату, или наоборот — мгновенно, прямо в браузере.","tool.html-entity-conv.name":"Кодировщик/декодировщик HTML-сущностей","tool.html-entity-conv.use":"Превращайте специальные символы в HTML-сущности — или превращайте любую кашу из сущностей обратно в обычный текст. Зарезервированные символы всегда безопасно экранируются, именованные сущности используются там, где они существуют, и всё работает мгновенно прямо в браузере.","tool.html-entity-conv.desc":"Преобразуйте текст в HTML-сущности (именованные, если есть, иначе числовые) или декодируйте любую кашу из сущностей обратно в текст — прямо в браузере.","tool.moon-phase-calc.name":"Калькулятор фаз Луны","tool.moon-phase-calc.use":"Посмотрите фазу, освещённость и возраст Луны сегодня одним взглядом или проверьте любую дату в прошлом или будущем — а также ближайшие полнолуние и новолуние.","tool.moon-phase-calc.desc":"Узнайте фазу Луны и освещённость сегодня мгновенно, или проверьте любую дату. Показывает возраст Луны и ближайшие даты полнолуния и новолуния — приближённый расчёт с точностью около ±1 дня.","tool.name-picker.name":"Случайный Выбор Имён","tool.name-picker.use":"Вставьте список, укажите, сколько победителей нужно, и встроенный генератор случайных чисел честно выберет их — с короткой анимацией ожидания перед показом результата.","tool.name-picker.desc":"Вставьте имена, выберите, сколько победителей выбрать сразу, и получите честный результат с анимацией. Удаляйте победителей или избегайте повторов между раундами — бесплатно и приватно.","tool.remove-duplicate-lines.name":"Удаление Повторяющихся Строк","tool.remove-duplicate-lines.use":"Вставьте список ниже — повторяющиеся строки исчезают мгновенно, а первое появление каждой сохраняется.","tool.remove-duplicate-lines.desc":"Вставьте список и удалите повторяющиеся строки, сохранив первое появление каждой — без учёта регистра, с обрезкой пробелов, сортировкой и режимом только дублей, всё в браузере.","tool.ring-size-conv.name":"Конвертер размеров колец","tool.ring-size-conv.use":"Какой у меня размер кольца в другой стране? Введите свой размер в формате US, UK, EU или Японии/Кореи — или измеренные миллиметры — и сразу увидите все соответствия.","tool.ring-size-conv.desc":"Переводите размер кольца между US/CA, буквами UK/AU, EU (окружность в мм) и Японией/Кореей (号) — с полной таблицей размеров и инструкцией по замеру дома.","tool.sql-formatter.name":"Форматировщик SQL","tool.sql-formatter.use":"Вставьте любой SQL-запрос, чтобы мгновенно отформатировать его с переносами строк и отступами по ключевым словам; выберите регистр ключевых слов — ВЕРХНИЙ, нижний или без изменений — либо переключитесь в режим минификации для компактной однострочной записи. Ничего не покидает ваш браузер.","tool.sql-formatter.desc":"Вставьте SQL-запрос, чтобы отформатировать его с отступами по ключевым словам, выберите регистр ключевых слов, или минифицируйте в одну строку — прямо в браузере.","tool.binary-text-conv.name":"Бинарный переводчик","tool.binary-text-conv.use":"Введите текст и мгновенно увидите его двоичный код, либо вставьте двоичные, шестнадцатеричные или десятичные значения байтов, чтобы декодировать их обратно в текст — ничего никогда не покидает ваш браузер.","tool.binary-text-conv.desc":"Конвертируйте текст в двоичный, hex или десятичный код байтов — и обратно, прямо в вашем браузере.","tool.chinese-zodiac-calc.name":"Калькулятор китайского зодиака","tool.chinese-zodiac-calc.use":"Какое у вас животное по китайскому гороскопу? Введите год рождения (и месяц/день, если родились близко к китайскому Новому году) — получите животное, стихию и полную таблицу лет.","tool.chinese-zodiac-calc.desc":"Введите год рождения и мгновенно узнайте своё животное и стихию по китайскому гороскопу. Добавьте месяц/день для точности по лунному Новому году. Бесплатно, только для развлечения.","tool.color-contrast-checker.name":"Проверка контрастности цветов","tool.color-contrast-checker.use":"Выберите цвет текста и цвет фона — коэффициент контрастности WCAG, значки AA/AAA и превью текста обновятся мгновенно. Работает с hex и RGB, а при провале подскажет доступный оттенок.","tool.color-contrast-checker.desc":"Введите цвет текста и фона, чтобы узнать коэффициент контрастности WCAG, статус AA/AAA, live-превью и советы по доступным оттенкам. Бесплатно, в браузере.","tool.cron-parser.name":"Парсер Cron-выражений","tool.cron-parser.use":"Вставьте cron-выражение вроде */15 9-17 * * 1-5 и узнайте, что оно означает простыми словами, а также следующие 5 моментов запуска.","tool.cron-parser.desc":"Вставьте cron-выражение из 5 полей и получите понятное расписание, следующие 5 запусков и разбор по каждому полю — прямо в браузере.","tool.csv-to-json.name":"Конвертер CSV в JSON","tool.csv-to-json.use":"Вставьте CSV или перетащите файл — мгновенно получите чистый массив JSON-объектов: поля в кавычках, разделитель и типы чисел обрабатываются автоматически.","tool.csv-to-json.desc":"Вставьте или перетащите CSV-файл и получите чистый массив JSON-объектов — поля в кавычках, определение разделителя и типы чисел/логических значений обрабатываются автоматически, всё в браузере.","tool.gradient-generator.name":"Генератор градиентов CSS","tool.gradient-generator.use":"Выберите тип градиента, перетащите цветовые точки и скопируйте готовый CSS — предпросмотр обновляется мгновенно по мере создания.","tool.gradient-generator.desc":"Создавайте линейные, радиальные и конические CSS-градиенты с помощью визуального редактора цветовых точек и копируйте готовый CSS мгновенно.","tool.gst-calc.name":"Калькулятор GST","tool.gst-calc.use":"Начислите GST на сумму без налога или выделите его из общей суммы — выберите индийскую ставку (5/12/18/28%) или ставку Австралии/Новой Зеландии/Сингапура, либо введите свою. Мгновенно получите сумму без налога, GST и итог с налогом, а для Индии — разбивку на CGST + SGST.","tool.gst-calc.desc":"Начисляйте или снимайте GST по любой ставке: индийские ставки (5/12/18/28%), Австралия (10%), Новая Зеландия (15%), Сингапур (9%), плюс разбивка CGST/SGST. Бесплатно, всё считается в браузере.","tool.inflation-calc.name":"Калькулятор инфляции","tool.inflation-calc.use":"Сколько стоил доллар тогда — в сегодняшних деньгах, и сколько забрала инфляция.","tool.inflation-calc.desc":"Введите сумму, среднегодовую инфляцию и число лет, чтобы узнать будущую покупательную способность, или измените направление, чтобы узнать, сколько стоит сегодня сумма из прошлого. Бесплатно, полностью работает в браузере.","tool.json-to-csv.name":"Конвертер JSON в CSV","tool.json-to-csv.use":"Вставьте JSON-массив объектов и мгновенно получите чистый, правильно оформленный в кавычки CSV — вложенные объекты разворачиваются в столбцы через точечную нотацию, заголовки объединяются по всем объектам, а результат можно скопировать или скачать. Полностью работает в вашем браузере.","tool.json-to-csv.desc":"Вставьте JSON-массив объектов и мгновенно получите чистый CSV — вложенные объекты разворачиваются в столбцы через точечную нотацию, корректное экранирование по RFC 4180, выбор разделителя запятая/точка с запятой/табуляция, всё в браузере.","tool.markdown-preview.name":"Просмотр Markdown","tool.markdown-preview.use":"Введите или вставьте Markdown слева и смотрите, как безопасно отрендеренный HTML-предпросмотр мгновенно обновляется справа — без регистрации, ничего не покидает ваш браузер.","tool.markdown-preview.desc":"Введите или вставьте Markdown и смотрите, как он мгновенно превращается в безопасный HTML — заголовки, жирный текст, ссылки, изображения, таблицы и блоки кода, всё вычисляется в браузере.","tool.oven-temp-conv.name":"Конвертер температуры духовки","tool.oven-temp-conv.use":"Введите температуру в Фаренгейтах или Цельсиях, либо выберите Gas Mark — остальные два значения обновятся мгновенно вместе с поправкой для конвекционной духовки.","tool.oven-temp-conv.desc":"Мгновенно переводите температуру духовки между Фаренгейтом, Цельсием и Gas Mark, с поправкой для конвекции — всё в браузере.","tool.remove-line-breaks.name":"Удалить разрывы строк","tool.remove-line-breaks.use":"Вставьте текст с разрывами строк, и он мгновенно объединится в один аккуратный блок — с пробелом, вообще без пробела, либо в умном режиме, который сохраняет абзацы и исправляет перенос строк при копировании из PDF.","tool.remove-line-breaks.desc":"Вставьте текст и уберите разрывы строк — объедините пробелом, без пробела, или используйте умный режим, который сохраняет абзацы и исправляет текст из PDF. Бесплатно, работает в браузере.","tool.reverse-text.name":"Генератор обратного текста","tool.reverse-text.use":"Введите или вставьте любой текст и получите сразу три перевёрнутые версии — порядок символов, порядок слов и буквы внутри каждого слова. Нажмите на карточку, чтобы скопировать.","tool.reverse-text.desc":"Переворачивайте любой текст тремя способами — порядок символов, слов или букв внутри каждого слова — мгновенно в браузере.","tool.shoe-size-conv.name":"Конвертер размеров обуви","tool.shoe-size-conv.use":"US 9 — это UK 8 и EU 42. Выберите таблицу, введите одно число, остальное посчитается.","tool.shoe-size-conv.desc":"Переводите размеры обуви между US, UK, EU и см (Япония/Азия) для мужчин, женщин и детей — с полными таблицами размеров.","tool.sort-lines.name":"Инструмент сортировки по алфавиту","tool.sort-lines.use":"Вставьте любой список и отсортируйте его от A до Z, от Z до A, в естественном порядке (item2 перед item10), по длине или перемешайте — всё в вашем браузере.","tool.sort-lines.desc":"Вставьте любой список и отсортируйте его от A до Z, от Z до A, в естественном порядке, по длине или перемешайте случайно — с возможностью учитывать регистр и игнорировать артикли, всё в браузере.","tool.square-root-calc.name":"Калькулятор квадратного корня","tool.square-root-calc.use":"Введите любое число, чтобы найти его квадратный, кубический или корень n-й степени — с точными ответами и упрощённой радикальной формой для идеальных степеней.","tool.square-root-calc.desc":"Находите квадратный, кубический или корень n-й степени любого числа, с точными результатами для идеальных степеней и упрощённой формой, например √72 = 6√2. Бесплатно, полностью работает в браузере.","tool.standard-deviation-calc.name":"Калькулятор стандартного отклонения","tool.standard-deviation-calc.use":"Вставьте список чисел и мгновенно получите выборочное и генеральное стандартное отклонение, дисперсию, среднее и сумму квадратов — с разворачиваемой пошаговой таблицей отклонений. Все вычисления происходят в вашем браузере.","tool.standard-deviation-calc.desc":"Вставьте список чисел, чтобы получить выборочное и генеральное стандартное отклонение, дисперсию, среднее и сумму квадратов, с пошаговой таблицей отклонений. Бесплатно, работает полностью в вашем браузере.","tool.text-to-speech.name":"Синтез речи","tool.text-to-speech.use":"Мгновенно превратите любой текст в речь. Вставьте текст, выберите голос, настройте скорость и высоту тона и нажмите воспроизведение — всё происходит прямо во вкладке вашего браузера.","tool.text-to-speech.desc":"Вставьте текст и прослушайте его встроенными голосами браузера — настройте скорость и высоту тона, затем воспроизведите, поставьте на паузу или остановите.","tool.vat-calc.name":"Калькулятор НДС","tool.vat-calc.use":"Начислите НДС на цену без налога или выделите его из цены с НДС — сумма без налога, НДС и итоговая цена появятся мгновенно.","tool.vat-calc.desc":"Начислите НДС на цену без налога или выделите его из цены с НДС по любой ставке, с быстрыми кнопками для распространённых ставок. Мгновенно увидите разбивку суммы без налога, НДС и итога — бесплатно, работает в браузере.","tool.zodiac-sign-calc.name":"Калькулятор знака зодиака","tool.zodiac-sign-calc.use":"Введите дату рождения, чтобы узнать свой западный (тропический) знак зодиака, его стихию и качество, а также короткое шуточное описание черт характера — плюс точный диапазон дат для всех 12 знаков.","tool.zodiac-sign-calc.desc":"Введите дату рождения, чтобы узнать свой западный знак зодиака, стихию и качество, а также короткое описание черт характера. Только для развлечения.","tool.metronome.name":"Онлайн-метроном","tool.metronome.use":"Задайте темп или отстучите его, выберите размер и нажмите «Старт» — точный метроном без лишнего, который держит стабильный ритм прямо в браузере.","tool.metronome.desc":"Бесплатный онлайн-метроном со слайдером BPM, функцией Tap Tempo и размерами такта (2/4, 3/4, 4/4, 6/8) на основе точного планирования Web Audio.","tool.ad-copy-limit-check.name":"Проверка длины рекламных текстов","tool.ad-copy-limit-check.use":"Вставьте заголовки и описания — каждая ячейка будет проверена по реальным лимитам площадок.","tool.ad-copy-limit-check.desc":"Бесплатный счётчик символов для рекламных текстов Google Ads, Microsoft Ads, Meta и Naver. Вставьте всю таблицу адаптивных поисковых объявлений и проверьте каждый заголовок и описание по реальным лимитам — корейские, японские и китайские символы считаются за два, как в Google. Работает полностью в вашем браузере.","tool.average-calc.name":"Калькулятор среднего значения","tool.average-calc.use":"Вставьте или введите список чисел — через запятую, пробел или с новой строки — и мгновенно получите среднее арифметическое, медиану, моду, размах и другое, приватно в вашем браузере.","tool.average-calc.desc":"Вставьте или введите список чисел и мгновенно получите среднее, медиану, моду, размах, минимум, максимум, сумму, количество и среднее геометрическое. Бесплатно, приватно, всё в браузере.","tool.barista-fire-calc.name":"Калькулятор Barista FIRE","tool.barista-fire-calc.use":"Barista FIRE — это полу-выход на пенсию с меньшим портфелем, потому что подработка покрывает часть ваших расходов, и инвестициям остаётся финансировать лишь остальное. Укажите расходы, ожидаемый доход от подработки и цель, чтобы увидеть ваше уменьшенное число Barista FIRE, насколько меньше нужно, чем при полном FIRE, и на верном ли пути ваши сбережения. Работает в любой валюте.","tool.barista-fire-calc.desc":"Бесплатный калькулятор Barista FIRE — укажите расходы, ожидаемый доход от подработки и ставку изъятия, чтобы увидеть меньший портфель, который нужен, когда подработка покрывает часть расходов: ваше число Barista FIRE, насколько оно меньше полного FIRE и дотянут ли до него ваши сбережения.","tool.cagr-calc.name":"Калькулятор CAGR","tool.cagr-calc.use":"Купили по одной цене, продали по другой? Введите начальное и конечное значение и период, чтобы за секунды получить среднегодовой темп роста (CAGR), общую доходность и мультипликатор роста. Вводите годы или даты. Работает в любой валюте.","tool.cagr-calc.desc":"Бесплатный калькулятор CAGR: введите начальное значение, конечное значение и период, чтобы получить среднегодовой темп роста, общую доходность, абсолютную прибыль и мультипликатор роста, а также таблицу роста по годам. Без входа, без рекламы, расчёт в браузере.","tool.calculator.name":"Научный калькулятор","tool.calculator.use":"Складывайте, вычитайте, умножайте и делите, или переключитесь в научный режим с тригонометрией, логарифмами, степенями, скобками и памятью — полноценный калькулятор, который работает на любом устройстве прямо в браузере.","tool.calculator.desc":"Бесплатный научный калькулятор с базовыми операциями, процентами, скобками, квадратным корнем, степенями, тригонометрией (градусы или радианы), логарифмами, памятью и историей вычислений — всё считается в вашем браузере.","tool.click-speed-test.name":"Тест скорости кликов (CPS)","tool.click-speed-test.use":"Как быстро вы можете кликать? Выберите длительность, нажмите на поле ниже и смотрите, как счётчик кликов в реальном времени превращается в результат CPS (кликов в секунду) с рангом от черепахи до гепарда.","tool.click-speed-test.desc":"Проверьте, как быстро вы можете кликать за 1–60 секунд, и получите результат CPS с рангом от черепахи до гепарда. Работает полностью в браузере.","tool.coast-fire-calc.name":"Калькулятор Coast FIRE","tool.coast-fire-calc.use":"Coast FIRE — это момент, когда ваши нынешние инвестиции сами дорастут до пенсионного числа — без новых взносов. Укажите возраст, возраст выхода на пенсию, текущие сбережения и цель, чтобы узнать, находитесь ли вы уже в Coast FIRE и сколько нужно сегодня, если ещё нет. Работает в любой валюте.","tool.coast-fire-calc.desc":"Бесплатный калькулятор Coast FIRE — укажите возраст, возраст выхода на пенсию, текущие сбережения и цель FIRE, чтобы узнать, дойдут ли ваши деньги до цели без новых взносов, в сегодняшних деньгах.","tool.compound-interest-calc.name":"Калькулятор сложных процентов","tool.compound-interest-calc.use":"Насколько вырастут ваши деньги? Введите сумму вклада, ставку, срок и периодичность начисления процентов, чтобы мгновенно увидеть итоговый баланс — начисление ежедневно, ежемесячно, ежеквартально или ежегодно, плюс необязательный ежемесячный взнос.","tool.compound-interest-calc.desc":"Бесплатный калькулятор сложных процентов: введите сумму вклада, годовую ставку, срок и периодичность начисления (ежедневно, ежемесячно, ежеквартально, ежегодно), плюс необязательный ежемесячный взнос, чтобы получить итоговый баланс, общую сумму взносов и общие проценты — с таблицей роста по годам. Без входа, без рекламы, расчёт в браузере.","tool.final-grade-calc.name":"Калькулятор итоговой оценки","tool.final-grade-calc.use":"Узнайте, сколько баллов нужно набрать на финальном экзамене, чтобы получить желаемую оценку — плюс быстрая таблица для A, B и C.","tool.final-grade-calc.desc":"Введите текущую оценку, желаемую итоговую оценку и вес финального экзамена — сразу узнайте, сколько баллов нужно набрать, плюс таблица баллов для A, B и C. Бесплатно, расчёт в браузере.","tool.grade-calc.name":"Калькулятор Оценок","tool.grade-calc.use":"Добавьте баллы и вес каждой работы — смотрите, как мгновенно обновляются ваша текущая средневзвешенная оценка и буквенная отметка.","tool.grade-calc.desc":"Бесплатный калькулятор средневзвешенной оценки — добавьте баллы и вес % каждой работы, чтобы мгновенно увидеть текущую оценку по курсу и буквенную отметку, с предупреждением, если сумма весов не равна 100%.","tool.height-conv.name":"Конвертер роста","tool.height-conv.use":"Введите рост в см, футах+дюймах, метрах или дюймах — остальные поля обновятся мгновенно.","tool.height-conv.desc":"Бесплатный конвертер роста — вводите в см, футах-дюймах, метрах или общих дюймах, остальное обновится мгновенно. Распознаёт формат 5'11\" и включает таблицу частых значений роста (150–200 см).","tool.hours-calc.name":"Калькулятор часов","tool.hours-calc.use":"Сколько часов между двумя моментами времени? Введите время начала и окончания, чтобы получить продолжительность в часах и минутах, а также в десятичных часах — ночная смена автоматически переносится на следующий день, а неоплачиваемый перерыв вычитается. Нужно прибавить или вычесть время? Переключите вкладку.","tool.hours-calc.desc":"Введите время начала и окончания, чтобы получить продолжительность в часах:минутах и десятичных часах, вычесть перерыв и учесть ночную смену. Также можно прибавить или вычесть часы и минуты из времени.","tool.image-compressor.name":"Компрессор изображений","tool.image-compressor.use":"Перетащите фото, выберите уровень качества — и получите файлы JPG, PNG или WebP меньшего размера за секунды. Всё сжатие происходит прямо в браузере, ничего не загружается.","tool.image-compressor.desc":"Сжимайте JPG, PNG и WebP прямо в браузере с помощью ползунка качества и опционального изменения размера — смотрите размер до/после и скачивайте, бесплатно и без загрузки на сервер.","tool.image-resizer.name":"Изменение размера изображений","tool.image-resizer.use":"Перетащите изображение JPG, PNG или WEBP — измените его размер по точным пикселям или в процентах, выберите формат и качество и скачайте результат. Изображение никогда не покидает ваш браузер.","tool.image-resizer.desc":"Измените размер любого изображения JPG, PNG или WEBP по точным пикселям или процентам — полностью в браузере, без загрузки на сервер.","tool.lorem-ipsum-gen.name":"Генератор Lorem Ipsum","tool.lorem-ipsum-gen.use":"Нужен текст-заполнитель для макета дизайна? Выберите абзацы, предложения или слова, мгновенно сгенерируйте классический Lorem Ipsum и скопируйте прямо в свой проект — обычным текстом или обёрнутым в теги HTML <p>.","tool.lorem-ipsum-gen.desc":"Генерируйте текст-заполнитель Lorem Ipsum по абзацам, предложениям или словам. Классическое начало, обёртка HTML <p> и статистика в реальном времени — по желанию. Бесплатно, расчёт в вашем браузере.","tool.macro-calc.name":"Калькулятор макросов","tool.macro-calc.use":"Знаете свою суточную калорийность или хотите рассчитать её по своим данным? Выберите сбалансированное, низкоуглеводное, высокобелковое, кето или собственное соотношение — и узнайте, сколько граммов белков, углеводов и жиров есть каждый день и в каждый приём пищи.","tool.macro-calc.desc":"Бесплатный калькулятор макросов — укажите суточные калории (или рассчитайте их) и получите белки, углеводы и жиры в граммах в день и на приём пищи, при любом соотношении.","tool.morse-code-translator.name":"Переводчик азбуки Морзе","tool.morse-code-translator.use":"Введите текст или вставьте код Морзе — второе поле обновится мгновенно. Прослушайте его как звук или скопируйте результат.","tool.morse-code-translator.desc":"Переводите текст в код Морзе или обратно прямо во время набора. Прослушивайте азбуку Морзе как звук с регулируемой скоростью и изучайте полную таблицу алфавита. Работает полностью в вашем браузере.","tool.mortgage-calc.name":"Ипотечный калькулятор","tool.mortgage-calc.use":"Введите сумму кредита — или стоимость жилья и первоначальный взнос — а также процентную ставку и срок, и сразу увидите ежемесячный платёж, общую сумму процентов, общую стоимость и полный погодовой график погашения.","tool.mortgage-calc.desc":"Бесплатный ипотечный калькулятор: введите сумму кредита (или стоимость жилья и первоначальный взнос), процентную ставку и срок, чтобы получить ежемесячный платёж, общую сумму процентов, общую выплату и полный график погашения. Без входа, без рекламы, расчёт в браузере.","tool.online-notepad.name":"Онлайн-блокнот","tool.online-notepad.use":"Начните печатать — и текст сохранится автоматически: без регистрации, без сервера, и ничего не потеряется при обновлении страницы. Счётчик слов и символов обновляется вживую, а хранить можно до 10 отдельных заметок одновременно.","tool.online-notepad.desc":"Бесплатный онлайн-блокнот, который автоматически сохраняет текст по мере ввода. Живой счётчик слов/символов, скачивание в .txt, копирование всего, до 5 заметок одновременно — ничего не загружается, всё остаётся в браузере.","tool.pace-calc.name":"Калькулятор темпа бега","tool.pace-calc.use":"Знаете две из трёх величин — дистанцию, время и темп? Введите их и мгновенно получите третью — плюс темп в мин/км и мин/милю, скорость в км/ч и милях/ч, и полная таблица сплитов для вашей дистанции.","tool.pace-calc.desc":"Введите любые две величины из трёх — дистанцию, время или темп — и получите третью, с темпом в мин/км и мин/милю, скоростью и таблицей сплитов.","tool.period-calc.name":"Калькулятор месячных","tool.period-calc.use":"Один цикл, три числа — узнайте даты 6 следующих месячных, день овуляции и фертильное окно.","tool.period-calc.desc":"Введите дату начала последних месячных, среднюю длину цикла и продолжительность менструации, чтобы увидеть даты следующих 6 циклов, а также предполагаемый день овуляции и фертильное окно. Бесплатно, приватно, расчёт в браузере.","tool.pregnancy-due-date-calc.name":"Калькулятор Даты Родов","tool.pregnancy-due-date-calc.use":"Введите дату последней менструации, дату зачатия или дату переноса эмбриона при ЭКО, чтобы узнать предполагаемую дату родов, текущий срок беременности и вехи каждого триместра.","tool.pregnancy-due-date-calc.desc":"Рассчитайте предполагаемую дату родов по последней менструации, дате зачатия или дате переноса эмбриона при ЭКО, а также узнайте срок беременности и вехи триместров. Бесплатно, приватно, прямо в браузере.","tool.regex-tester.name":"Тестер регулярных выражений","tool.regex-tester.use":"Введите шаблон и флаги, вставьте тестовую строку и смотрите, как совпадения подсвечиваются вживую — с группами захвата, счётчиком совпадений и предпросмотром замены. Всё работает прямо в вашем браузере.","tool.regex-tester.desc":"Тестируйте регулярные выражения JavaScript вживую с подсветкой совпадений, группами захвата и предпросмотром замены — всё в браузере.","tool.tdee-calc.name":"Калькулятор TDEE","tool.tdee-calc.use":"Сколько калорий вы сжигаете за день? Укажите возраст, пол, рост, вес и уровень активности — получите TDEE, BMR и калории для поддержания, похудения или набора массы.","tool.tdee-calc.desc":"Укажите возраст, пол, рост, вес и уровень активности, чтобы узнать TDEE, BMR и калории для похудения или набора массы.","tool.text-diff.name":"Сравнение текстов","tool.text-diff.use":"Вставьте исходный и изменённый текст ниже, чтобы увидеть, что именно было добавлено, удалено или изменено — построчно и по словам.","tool.text-diff.desc":"Вставьте два текста и мгновенно увидите каждую добавленную, удалённую и изменённую строку и слово. Бесплатный построчный компаратор с опциями регистра и пробелов, всё в браузере.","tool.typing-test.name":"Тест скорости печати","tool.typing-test.use":"Печатайте слова, которые появляются на экране, и следите за скоростью печати в реальном времени. Выберите 30 секунд, 1 минуту или 3 минуты и получите чистый WPM, точность и количество символов — бесплатно, без регистрации, всё в вашем браузере.","tool.typing-test.desc":"Проверьте скорость печати за 30 секунд, 1 минуту или 3 минуты. Печатайте настоящие слова и мгновенно получайте WPM, точность % и количество символов — бесплатно, расчёт полностью в браузере.","guide.heading":"О Toolhub","guide.lead":"Toolhub — растущая коллекция бесплатных веб-инструментов для небольших расчётов и преобразований, которые возникают каждый день: от проверки, какая упаковка дешевле, до подсчёта символов в тексте. Каждый инструмент работает сразу при открытии: без установки, без аккаунтов, без ожидания.","guide.useTitle":"Как найти нужный инструмент","guide.useBody":"Просмотрите каталог выше — он сгруппирован по категориям: «Финансы и покупки», «Здоровье и тело», «Единицы и конвертация», «Дата и время» и «Инструменты разработчика». Спешите? Введите ключевое слово в поиск — «цена за единицу», «ИМТ», «таймер» — и список фильтруется по мере ввода. Нажмите на любой инструмент, чтобы открыть его на отдельной странице, и переключите весь сайт на один из 14 языков в шапке.","guide.howTitle":"Приватность по замыслу","guide.howBody":"Каждый инструмент Toolhub — это чисто статическая страница: всё, что вы вводите, обрабатывается целиком в вашем браузере и никогда не отправляется на сервер. Нет регистрации и не нужно никому передавать цифры, поэтому вы можете спокойно рассчитать зарплату, кредит или личный счёт. Сохраняются только ваши настройки темы и языка — и они остаются в локальном хранилище этого браузера.","guide.tipTitle":"Бесплатно и постоянно пополняется","guide.tipBody":"Все инструменты полностью бесплатны, без подписок и скрытых платежей. Новые инструменты добавляются регулярно и появляются на этой странице сразу после запуска, так что страницу стоит добавить в закладки. Если нужного инструмента нет, скорее всего, он уже в разработке.","meta.title":"Toolhub — бесплатные онлайн-инструменты без регистрации","meta.description":"От сравнения цен до подсчёта символов: бесплатные веб-инструменты, работающие прямо в браузере. Без установки и без аккаунтов.","nav.theme":"Сменить тему","nav.share":"Поделиться","nav.language":"Язык","hero.lede":"Бесплатные веб-инструменты, готовые к работе в нужный момент — без установки и регистрации.","flagship.desc":"Платформа анализа социальных трендов для авторов и инфлюенсеров. Анализ ключевых слов, радар конкурентов и архив сигналов в одном месте.","tools.heading":"Все инструменты","tools.viewall":"Показать все","tools.searchLabel":"Поиск инструментов","tools.searchPlaceholder":"Искать по названию (напр.: цена за единицу)","tools.empty":"Ничего не найдено. Попробуйте другой запрос.","tool.unit-price.name":"Калькулятор цены за единицу","tool.unit-price.use":"Просто введите цену и количество. Мы сразу подскажем, что выгоднее.","cat.finance":"Финансы и покупки","cat.life":"Повседневная жизнь","cat.random":"Случайное и веселье","cat.dev":"Инструменты разработчика","cat.date":"Дата и время","cat.health":"Здоровье и тело","cat.units":"Единицы и конвертация","cat.text":"Текст","cat.utility":"Утилиты","tool.unit-price.desc":"Большая упаковка или маленькая — за секунды узнайте, что на самом деле дешевле","tool.sleep-cycle-calc.name":"Калькулятор циклов сна","tool.sleep-cycle-calc.use":"Во сколько лечь спать, чтобы проснуться бодрым? За секунды получите время отхода ко сну, завершающее полные 90-минутные циклы сна.","tool.sleep-cycle-calc.desc":"Во сколько лечь спать, чтобы проснуться бодрым? За секунды получите время отхода ко сну, завершающее полные 90-минутные циклы сна.","tool.gpa-calc.name":"Калькулятор GPA","tool.gpa-calc.use":"Добавьте курсы, кредиты и оценки — мгновенно получите GPA за семестр и накопительный в любой шкале.","tool.gpa-calc.desc":"Добавьте курсы, кредиты и оценки — мгновенно получите GPA за семестр и накопительный в любой шкале.","tool.fuel-cost-calc.name":"Калькулятор расходов на топливо","tool.fuel-cost-calc.use":"Во сколько обойдётся эта поездка по топливу? Выберите страну — единицы и валюту настроим мы — и введите расстояние, расход и цену.","tool.fuel-cost-calc.desc":"Во сколько обойдётся эта поездка по топливу? Введите расстояние, расход и цену — и узнаете мгновенно.","tool.random-number-gen.name":"Генератор случайных чисел","tool.random-number-gen.use":"Задайте диапазон, выберите количество и мгновенно получите непредвзятые случайные числа — или быстрые лотерейные комбинации для Powerball, Mega Millions, EuroMillions и Lotto 6/45.","tool.random-number-gen.desc":"Задайте диапазон, выберите количество и мгновенно получите непредвзятые случайные числа — или быстрые лотерейные комбинации для Powerball, Mega Millions, EuroMillions и Lotto 6/45.","tool.dice-roller.name":"Бросок кубиков","tool.dice-roller.use":"Выберите кубик и бросьте — или введите нотацию вроде 2d6+3. Честные результаты, прямо в вашем браузере.","tool.dice-roller.desc":"Выберите кубик и бросьте — или введите нотацию вроде 2d6+3. Честные результаты, прямо в вашем браузере.","tool.coin-flipper.name":"Подбросить монету","tool.coin-flipper.use":"Орёл или решка? Нажмите на монету и мгновенно получите честный результат 50/50 — подбросьте сразу много монет ради статистики или назовите стороны, чтобы решить что угодно.","tool.coin-flipper.desc":"Орёл или решка? Нажмите на монету и мгновенно получите честный результат 50/50 — подбросьте сразу много монет ради статистики или назовите стороны, чтобы решить что угодно.","tool.url-encoder.name":"URL-кодировщик / декодировщик","tool.url-encoder.use":"Мгновенно кодируйте и декодируйте URL в процентах. Выберите режим «Компонент» или «Полный URL», включите кодирование форм (+) и сохраните каждый символ — корейский, эмодзи, CJK — без потерь. Ничего не покидает ваш браузер.","tool.url-encoder.desc":"Мгновенно кодируйте и декодируйте URL в процентах. Выберите режим «Компонент» или «Полный URL», включите кодирование форм (+) и сохраните каждый символ — корейский, эмодзи, CJK — без потерь. Ничего не покидает ваш браузер.","tool.hash-gen.name":"Генератор хешей","tool.hash-gen.use":"Вставьте текст или перетащите файл, чтобы мгновенно получить его хеши MD5, SHA-1, SHA-256, SHA-384 и SHA-512. Проверьте контрольную сумму, вставив ожидаемое значение, — всё в браузере.","tool.hash-gen.desc":"Вставьте текст или перетащите файл, чтобы мгновенно получить его хеши MD5, SHA-1, SHA-256, SHA-384 и SHA-512. Проверьте контрольную сумму, вставив ожидаемое значение, — всё в браузере.","tool.color-picker.name":"Палитра и конвертер цвета","tool.color-picker.use":"Выберите цвет или вставьте любой код — мгновенно получите HEX, RGB, HSL, HSV и CMYK с копированием в один клик. Всё остаётся в вашем браузере.","tool.unix-timestamp-conv.name":"Конвертер Unix-времени","tool.unix-timestamp-conv.use":"Вставьте число, скопированное из лога. Единицы измерения определим сами.","tool.fraction-calc.name":"Калькулятор дробей","tool.fraction-calc.use":"Введите две дроби, выберите операцию и получите точный ответ, сокращённый до несократимого вида — с шагами.","tool.prime-checker.name":"Проверка простых чисел","tool.prime-checker.use":"Введите целое число — мгновенно узнайте, простое ли оно, и посмотрите его разложение на простые множители.","tool.roman-numeral-conv.name":"Конвертер римских цифр","tool.roman-numeral-conv.use":"Введите число или римскую запись — сразу получите обратное, с разбором.","tool.exchange-rate-conv.name":"Конвертер валют","tool.exchange-rate-conv.use":"Введите сумму и выберите две валюты, чтобы мгновенно получить сегодняшнее конвертированное значение. Дата курса всегда показана, и расчёт продолжается по сохранённым курсам даже офлайн.","tool.ovulation-calc.name":"Калькулятор овуляции","tool.ovulation-calc.use":"Одна дата — последние месячные — и день овуляции с фертильными днями сразу видны в календаре.","tool.color-picker.desc":"Выберите цвет или вставьте любой код — мгновенно получите HEX, RGB, HSL, HSV и CMYK с копированием в один клик. Всё остаётся в вашем браузере.","tool.json-formatter.name":"Форматтер JSON","tool.json-formatter.use":"Вставьте JSON, чтобы мгновенно отформатировать, проверить или минифицировать его — с точной строкой и столбцом любой ошибки. Ничто не покидает ваш браузер.","tool.json-formatter.desc":"Вставьте JSON, чтобы мгновенно отформатировать, проверить или минифицировать его — с точной строкой и столбцом любой ошибки. Ничто не покидает ваш браузер.","tool.base64-conv.name":"Base64 кодировщик / декодировщик","tool.base64-conv.use":"Мгновенно кодируйте и декодируйте Base64 — текст или изображения. Полная поддержка UTF-8 (корейский, эмодзи, CJK), опция URL-safe, и всё остаётся в вашем браузере.","tool.base64-conv.desc":"Мгновенно кодируйте и декодируйте Base64 — текст или изображения. Полная поддержка UTF-8 (корейский, эмодзи, CJK), опция URL-safe, и всё остаётся в вашем браузере.","tool.uuid-gen.name":"Генератор UUID","tool.uuid-gen.use":"Нажмите «Сгенерировать», чтобы получить новый UUID по RFC 4122. Создавайте до 500 за раз и копируйте все сразу.","tool.uuid-gen.desc":"Нажмите «Сгенерировать», чтобы получить новый UUID по RFC 4122. Создавайте до 500 за раз и копируйте все сразу.","tool.child-height-predictor.name":"Калькулятор роста ребёнка","tool.child-height-predictor.use":"Каким будет рост вашего ребёнка? Оцените взрослый рост по росту мамы и папы за секунды.","tool.child-height-predictor.desc":"Каким будет рост вашего ребёнка? Оцените взрослый рост по росту мамы и папы за секунды.","tool.speed-conv.name":"Конвертер скорости","tool.speed-conv.use":"Введите число один раз — сразу увидите его во всех единицах скорости.","tool.speed-conv.desc":"Введите число один раз — сразу увидите его во всех единицах скорости.","tool.case-converter.name":"Конвертер регистра","tool.case-converter.use":"Вставьте текст и получите все варианты регистра сразу — UPPERCASE, строчные, Заголовок, camelCase, snake_case и другое. Нажмите на любую карточку, чтобы скопировать.","tool.case-converter.desc":"Вставьте текст и получите все варианты регистра сразу — UPPERCASE, строчные, Заголовок, camelCase, snake_case и другое. Нажмите на любую карточку, чтобы скопировать.","tool.blood-alcohol-calc.name":"Калькулятор алкоголя в крови (BAC)","tool.blood-alcohol-calc.use":"Укажите напитки и посмотрите оценку BAC — это учебный ориентир, а не разрешение садиться за руль.","tool.blood-alcohol-calc.desc":"Укажите напитки и посмотрите оценку BAC — это учебный ориентир, а не разрешение садиться за руль.","tool.data-size-conv.name":"Конвертер размера данных","tool.data-size-conv.use":"Введите число один раз — и сразу увидите его в каждой единице данных, десятичной и двоичной.","tool.data-size-conv.desc":"Введите число один раз — и сразу увидите его в каждой единице данных, десятичной и двоичной.","tool.ideal-weight-calc.name":"Калькулятор идеального веса","tool.ideal-weight-calc.use":"Идеальный вес — не одно число: сравните четыре проверенные формулы и здоровый диапазон ИМТ с одного взгляда.","tool.ideal-weight-calc.desc":"Идеальный вес — не одно число: сравните четыре проверенные формулы и здоровый диапазон ИМТ с одного взгляда.","tool.water-intake-calc.name":"Калькулятор потребления воды","tool.water-intake-calc.use":"Достаточно одного числа. Узнайте, сколько воды выпить сегодня — в стаканах и бутылках.","tool.water-intake-calc.desc":"Достаточно одного числа. Узнайте, сколько воды выпить сегодня — в стаканах и бутылках.","tool.workday-calc.name":"Калькулятор рабочих дней","tool.workday-calc.use":"Выберите две даты. Выходные и праздники вычитаются автоматически.","tool.workday-calc.desc":"Выберите две даты. Выходные и праздники вычитаются автоматически.","tool.time-zone-conv.name":"Конвертер часовых поясов","tool.time-zone-conv.use":"Выберите время и несколько городов. Смещения и летнее время мы посчитаем за вас.","tool.time-zone-conv.desc":"Выберите время и несколько городов. Смещения и летнее время мы посчитаем за вас.","tool.area-conv.name":"Конвертер площади","tool.area-conv.use":"Введите число один раз — и сразу увидите его в каждой единице площади.","tool.area-conv.desc":"Введите число один раз — и сразу увидите его в каждой единице площади.","tool.volume-conv.name":"Конвертер объёма","tool.volume-conv.use":"Введите число один раз — и сразу увидите его во всех единицах объёма.","tool.volume-conv.desc":"Введите число один раз — и сразу увидите его во всех единицах объёма.","tool.tip-calc.name":"Калькулятор чаевых","tool.tip-calc.use":"Сколько оставить чаевых? Введите сумму счёта — чаевые и доля каждого появятся мгновенно.","tool.tip-calc.desc":"Сколько оставить чаевых? Введите сумму счёта — чаевые и доля каждого появятся мгновенно.","tool.split-bill-calc.name":"Калькулятор деления счёта","tool.split-bill-calc.use":"Сумма, делённая на людей — чаевые и округление учтены. Скопируйте долю каждого в групповой чат.","tool.split-bill-calc.desc":"Сумма, делённая на людей — чаевые и округление учтены. Скопируйте долю каждого в групповой чат.","tool.calorie-calc.name":"Калькулятор сожжённых калорий","tool.calorie-calc.use":"Сколько калорий сожгла эта тренировка? Три поля — ответ за три секунды.","tool.calorie-calc.desc":"Сколько калорий сожгла эта тренировка? Три поля — ответ за три секунды.","tool.word-counter.name":"Счётчик слов","tool.word-counter.use":"Вставьте текст и мгновенно получите подсчёты: слова, символы, предложения, абзацы, а также время чтения и произношения.","tool.word-counter.desc":"Вставьте текст и мгновенно получите подсчёты: слова, символы, предложения, абзацы, а также время чтения и произношения.","tool.weight-conv.name":"Конвертер веса","tool.weight-conv.use":"Введите число один раз — и сразу увидите его во всех 9 единицах массы.","tool.weight-conv.desc":"Введите число один раз — и сразу увидите его во всех 9 единицах массы.","tool.stopwatch.name":"Секундомер онлайн","tool.stopwatch.use":"Пробел — старт и пауза, L — круг. Точен даже в фоновой вкладке.","tool.stopwatch.desc":"Пробел — старт и пауза, L — круг. Точен даже в фоновой вкладке.","tool.temp-conv.name":"Конвертер температуры","tool.temp-conv.use":"Введите в любое поле — два других обновятся мгновенно.","tool.temp-conv.desc":"Введите в любое поле — два других обновятся мгновенно.","tool.length-conv.name":"Конвертер длины","tool.length-conv.use":"Введите число один раз — и сразу увидите его во всех 8 единицах длины.","tool.length-conv.desc":"Введите число один раз — и сразу увидите его во всех 8 единицах длины.","tool.loan-calc.name":"Кредитный калькулятор","tool.loan-calc.use":"Введите сумму кредита, процентную ставку и срок — ежемесячный платёж, общая переплата и полный график погашения появляются мгновенно, три способа погашения сравниваются на одном экране.","tool.loan-calc.desc":"Введите сумму кредита, процентную ставку и срок — ежемесячный платёж, общая переплата и полный график погашения появляются мгновенно, три способа погашения сравниваются на одном экране.","tool.savings-calc.name":"Калькулятор накоплений","tool.savings-calc.use":"Сколько накопится, если откладывать каждый месяц? Получите сумму на конец срока — проценты, удержанный налог и чистыми на руки — за секунды. Работает в любой валюте.","tool.savings-calc.desc":"Сколько накопится, если откладывать каждый месяц? Получите сумму на конец срока — проценты, удержанный налог и чистыми на руки — за секунды. Работает в любой валюте.","tool.body-fat-calc.name":"Калькулятор процента жира","tool.body-fat-calc.use":"Без сканера InBody — оцените процент жира с помощью обычной сантиметровой ленты.","tool.body-fat-calc.desc":"Без сканера InBody — оцените процент жира с помощью обычной сантиметровой ленты.","tool.world-clock.name":"Мировые часы","tool.world-clock.use":"Добавьте город — и часы пойдут. Разницу во времени мы посчитаем за вас.","tool.world-clock.desc":"Добавьте город — и часы пойдут. Разницу во времени мы посчитаем за вас.","tool.bmr-calc.name":"Калькулятор базального метаболизма","tool.bmr-calc.use":"Калории, которые вы тратите, просто дыша, — узнайте точно по двум проверенным формулам.","tool.bmr-calc.desc":"Калории, которые вы тратите, просто дыша, — узнайте точно по двум проверенным формулам.","tool.countdown-timer.name":"Таймер обратного отсчёта","tool.countdown-timer.use":"Задайте время и нажмите «Старт». Сигнал прозвучит ровно в момент окончания — даже в фоновой вкладке.","tool.countdown-timer.desc":"Задайте время и нажмите «Старт». Сигнал прозвучит ровно в момент окончания — даже в фоновой вкладке.","tool.qr-gen.name":"Генератор QR-кодов","tool.qr-gen.use":"QR-код появляется, пока вы печатаете. Без регистрации, без срока действия — данные не покидают браузер.","tool.qr-gen.desc":"QR-код появляется, пока вы печатаете. Без регистрации, без срока действия — данные не покидают браузер.","tool.date-diff-calc.name":"Калькулятор разницы дат","tool.date-diff-calc.use":"Просто выберите две даты — сколько дней, лет и месяцев, видно сразу.","tool.date-diff-calc.desc":"Просто выберите две даты — сколько дней, лет и месяцев, видно сразу.","tool.interest-calc.name":"Калькулятор процентов","tool.interest-calc.use":"Сколько процентов принесёт вложенная сумма? Простые или сложные, за вычетом налога — реальная выплата мгновенно.","tool.interest-calc.desc":"Сколько процентов принесёт вложенная сумма? Простые или сложные, за вычетом налога — реальная выплата мгновенно.","tool.pomodoro-timer.name":"Помодоро-таймер","tool.pomodoro-timer.use":"25 минут фокуса, 5 минут отдыха. Цикл таймер крутит сам.","tool.pomodoro-timer.desc":"25 минут фокуса, 5 минут отдыха. Цикл таймер крутит сам.","tool.char-count.name":"Счётчик символов","tool.char-count.use":"Просто вставьте текст. Число символов, слов и байтов — сразу, прямо в браузере.","tool.char-count.desc":"Вставьте текст — мгновенный подсчёт символов, слов и байтов","tool.age-calc.name":"Калькулятор возраста","tool.age-calc.use":"Одна дата рождения — и вы знаете точный возраст, корейский возраст и знак китайского гороскопа. Всего три секунды.","tool.age-calc.desc":"Точный возраст, корейский счёт лет и знак зодиака мгновенно","tool.bmi-calc.name":"Калькулятор ИМТ","tool.bmi-calc.use":"Достаточно двух чисел. Смотрите свой индекс массы тела сразу по критериям ВОЗ и Азиатско-Тихоокеанского региона.","tool.bmi-calc.desc":"Введите рост и вес — мгновенный индекс массы тела","tool.dday-calc.name":"Счётчик дней (D-Day)","tool.dday-calc.use":"Выберите целевую дату — отсчёт начнётся сразу. Экзамены, годовщины, дедлайны — что угодно.","tool.dday-calc.desc":"Обратный отсчёт до экзаменов, годовщин и дедлайнов","tool.discount-calc.name":"Калькулятор скидок","tool.discount-calc.use":"Введите исходную и акционную цену, чтобы узнать скидку — или наоборот. В обе стороны, мгновенно.","tool.discount-calc.desc":"Цена со скидкой или процент скидки — мгновенно в обе стороны","tool.password-gen.name":"Генератор паролей","tool.password-gen.use":"Криптографически стойкие случайные пароли — без рекламы и сервера.","tool.password-gen.desc":"Криптостойкие случайные пароли — без сервера и рекламы","tool.percent-calc.name":"Калькулятор процентов","tool.percent-calc.use":"Никаких формул для запоминания. Введите числа — ответ появится сразу.","tool.percent-calc.desc":"Доли, процент изменения и разницы — на одной вкладке","tool.salary-calc.name":"Зарплатный калькулятор (Корея)","tool.salary-calc.use":"Введите годовую зарплату в Южной Корее — и сразу увидите, сколько получите на руки в месяц. Актуальные корейские ставки 2026 года.","tool.salary-calc.desc":"Введите годовую зарплату — месячная на руки по корейским налогам","tool.tax-calc.name":"Калькулятор НДС (Корея 10%)","tool.tax-calc.use":"Просто введите сумму. Ставка НДС вашей страны применяется автоматически — сумма без налога, налог и итого появятся сразу.","tool.tax-calc.desc":"Мгновенно разложите сумму на цену без налога и НДС 10%","usage.heading":"Как пользоваться инструментами","usage.unit-price.title":"Калькулятор цены за единицу — как пользоваться","usage.unit-price.body":"Стоите в магазине и не понимаете, что выгоднее: порошок 500 г или 1,2 кг? Введите цену и объём каждого товара — калькулятор приведёт оба к цене за 100 г и сразу покажет разницу. Для наборов вроде «2+1 в подарок» укажите количество штук в наборе, и реальная цена будет рассчитана по общему объёму. Без регистрации и установки — ваши числа не покидают браузер.","usage.char-count.title":"Счётчик символов — как пользоваться","usage.char-count.body":"Пишете с ограничением по символам — сопроводительное письмо, эссе, пост или мета-описание? Вставьте текст, и вы сразу увидите количество символов с пробелами и без, а также сколько осталось до вашего лимита. Для систем, ограничивающих по байтам, показывается и число байтов (UTF-8 и EUC-KR). Всё считается внутри браузера; на сервер ничего не отправляется, так что даже конфиденциальный текст вставлять безопасно.","others.heading":"Другие проекты команды","others.lede":"Посмотрите другие сервисы команды, создавшей Toolhub.","others.sta.desc":"Платформа анализа социальных трендов для авторов и инфлюенсеров","others.isitai.name":"Is It AI? (isitai.me)","others.isitai.desc":"Бесплатная проверка, создано ли изображение или видео ИИ","faq.heading":"Часто задаваемые вопросы","faq.q1":"Что такое Toolhub?","faq.a1":"Toolhub — это коллекция бесплатных онлайн-инструментов вроде калькулятора цены за единицу для повседневных задач. Ничего не нужно устанавливать и нигде не нужно регистрироваться: откройте браузер — и всё работает. Каждый инструмент решает одну задачу, быстро.","faq.q2":"Все инструменты бесплатны?","faq.a2":"Да. Каждый инструмент в Toolhub полностью бесплатен — без платежей и подписок. Если когда-нибудь появится платная функция, об этом будет ясно сказано на странице инструмента.","faq.q3":"Отправляются ли мои данные на сервер?","faq.a3":"Нет. Инструменты Toolhub — это чисто статические страницы: ввод обрабатывается целиком в вашем браузере и никуда не передаётся. Настройки вроде темы и языка хранятся только в localStorage этого браузера.","faq.q4":"Как часто появляются новые инструменты?","faq.a4":"Новые инструменты и улучшения публикуются по мере готовности. Каталог содержит доступные инструменты; фиксированного недельного графика нет.","footer.privacy":"Политика конфиденциальности","footer.more":"Больше инструментов","footer.credit":"Создано rayv","footer.coffee":"☕ Угостите меня кофе","why.heading":"Почему Toolhub","why.free.title":"Без регистрации, всегда бесплатно","why.free.body":"Каждый инструмент полностью бесплатен и работает без учётной записи. Просто откройте и начните — без установки, без подписок, без скрытых платежей.","why.private.title":"Работает в вашем браузере","why.private.body":"Все вычисления выполняются на вашем устройстве. Всё, что вы вводите, обрабатывается внутри браузера и никогда его не покидает, поэтому ваши данные остаются конфиденциальными.","why.maintained.title":"Еженедельное обслуживание","why.maintained.body":"Каждый инструмент выходит только после прохождения контрольного списка качества, а вся коллекция проверяется каждую неделю, чтобы расчёты оставались верными, а ссылки — рабочими.","footer.about":"О проекте","footer.contact":"Контакты","footer.terms":"Условия","tool.crypto-average-calc.name":"Калькулятор средней цены криптовалюты","tool.crypto-average-calc.use":"Покупали монету в несколько заходов? Введите каждую покупку и за секунды получите средневзвешенную цену, точку безубыточности и нереализованную прибыль/убыток, а затем спланируйте докупку на просадке, чтобы снизить среднюю. Поддерживает дробные монеты и любую фиатную валюту.","tool.csv-dedupe.name":"Удаление дубликатов CSV","tool.csv-dedupe.use":"Выберите столбцы, определяющие дубликат, и очистите список — ничего не загружается и не удаляется молча.","tool.dca-calc.name":"Калькулятор инвестиций DCA/SIP","tool.dca-calc.use":"Инвестируете фиксированную сумму каждый месяц? Спрогнозируйте будущий портфель за секунды — всего внесено, рыночная прибыль, налог и сколько это реально стоит после инфляции. Работает в любой валюте.","tool.inventory-turnover.name":"Оборачиваемость запасов и поиск неликвидов","tool.inventory-turnover.use":"Оборачиваемость по каждому SKU, дни запаса и деньги, замороженные в неходовых товарах — всё считается в вашем браузере.","tool.investment-goal-calc.name":"Калькулятор инвестиционной цели","tool.investment-goal-calc.use":"Есть число на уме? Укажите цель, сколько у вас времени и ожидаемую доходность, чтобы найти ежемесячный взнос, который вас туда приведёт — или разовую сумму, которую можно вложить сегодня. Посмотрите, сколько это ваши деньги, а сколько рыночный рост. Работает в любой валюте.","tool.landed-cost-batch.name":"Пакетный калькулятор полной себестоимости им","tool.landed-cost-batch.use":"Распределите фрахт по всем позициям и получите себестоимость единицы — в браузере, без загрузки данных.","tool.list-compare.name":"Сравнить два списка","tool.list-compare.use":"Найдите, что только в A, только в B и в обоих — в вашем браузере, ничего не загружается.","tool.manday-estimator.name":"Калькулятор трудозатрат в человеко-месяцах","tool.manday-estimator.use":"Вставьте WBS. Человеко-часы, человеко-дни и человеко-месяцы группируются по ролям и этапам — с затратами.","tool.packing-list-cbm.name":"Калькулятор CBM и оплачиваемого веса по упак","tool.packing-list-cbm.use":"Вставьте сотни строк коробок. Получите CBM, оплачиваемый вес, R/T и число контейнеров — без аккаунта и без загрузки на сервер.","tool.paygap-report.name":"Отчёт о гендерном разрыве в оплате","tool.paygap-report.use":"Перетащите CSV платёжной ведомости и получите обязательные средний/медианный разрывы в оплате, бонусные разрывы и зарплатные квартили — всё считается в вашем браузере и никогда не загружается.","tool.perf-rating-calibrator.name":"Калибратор оценок эффективности","tool.perf-rating-calibrator.use":"Приведите мягких и строгих оценивающих к единой шкале, затем примените своё распределение по грейдам — полностью в браузере.","tool.pregnancy-week-calc.name":"Калькулятор срока беременности","tool.pregnancy-week-calc.use":"Сколько у вас недель и когда ждать малыша? Достаточно одной даты — первого дня последней менструации.","tool.roi-calc.name":"Калькулятор ROI","tool.roi-calc.use":"Введите, сколько вложили и сколько вернули, чтобы за секунды увидеть окупаемость инвестиций (ROI), чистую прибыль и мультипликатор возврата. Добавьте срок владения — в годах или датах — чтобы получить также годовой ROI. Работает в любой валюте.","tool.safety-stock-batch.name":"Пакетный калькулятор страхового запаса и точ","tool.safety-stock-batch.use":"Все SKU в одной таблице. Отклонение спроса мы считаем из вашей истории — вам не нужно искать Z-значение.","tool.stock-average-calc.name":"Калькулятор средней цены акции","tool.stock-average-calc.use":"Покупали акцию в несколько заходов? Введите каждую покупку и за секунды получите средневзвешенную цену, точку безубыточности и нереализованную прибыль/убыток, а затем спланируйте усреднение вниз. Работает в любой валюте.","tool.stock-ledger-recon.name":"Складская книга и сверка инвентаризации","tool.stock-ledger-recon.use":"Постройте по каждому SKU начальный → приход → расход → конечный остаток из журнала движений и увидьте точно, где фактическая инвентаризация не сходится — целиком в вашем браузере.","tool.stock-profit-calc.name":"Калькулятор прибыли по акциям","tool.stock-profit-calc.use":"Продали акцию и хотите знать, сколько реально заработали? Введите цену покупки, цену продажи и количество, чтобы за секунды увидеть чистую прибыль, доходность % и безубыточность, затем добавьте комиссии за покупку/продажу, налог на сделку и налог на прирост капитала для суммы после налога. Работает в любой валюте.","tool.timesheet-batch-agg.name":"Пакетный агрегатор табелей","tool.timesheet-batch-agg.use":"Превратите сырой CSV с отметками в обычные, сверхурочные, ночные и праздничные часы по сотруднику и по неделям — всё считается в браузере и никуда не загружается.","tool.aspect-ratio-calc.name":"Калькулятор соотношения сторон","tool.aspect-ratio-calc.use":"Пропорции сохраняются. Введите одно новое значение — второе посчитается.","tool.cooking-conv.name":"Перевод чашек в граммы","tool.cooking-conv.use":"Объём в вес по каждому продукту — единственный честный способ пересчёта чашек.","tool.dog-age-calc.name":"Калькулятор возраста собаки","tool.dog-age-calc.use":"Правило «умножить на семь» неверно: размер и жизненный этап меняют всё.","tool.one-rep-max-calc.name":"Калькулятор 1ПМ","tool.one-rep-max-calc.use":"Один тяжёлый подход даёт оценку 1ПМ и рабочие веса, которые из неё следуют.","tool.square-footage-calc.name":"Калькулятор площади","tool.square-footage-calc.use":"Замерьте комнату — получите площадь и реальный объём закупки.","tool.number-base-conv.name":"Конвертер систем счисления","tool.number-base-conv.use":"Введите число в любой системе — остальные появятся сразу.","tool.color-conv.name":"Конвертер HEX в RGB","tool.color-conv.use":"Один цвет на входе — три формата на выходе, плюс проверка контраста, о которой забывают.","tool.jwt-decoder.name":"Декодер JWT","tool.jwt-decoder.use":"Декодируйте токен, читайте claim-ы и срок действия — ничего никуда не отправляя.","tool.wheel-spinner.name":"Случайная рулетка","tool.wheel-spinner.use":"По одной записи в строке, один запуск — один победитель, с возможностью удалить и повторить.","tool.sales-tax-calc.name":"Калькулятор налога с продаж США","tool.sales-tax-calc.use":"От цены к итогу и обратно — базовые ставки всех штатов уже внутри.","tool.overtime-pay-calc.name":"Калькулятор оплаты сверхурочных","tool.overtime-pay-calc.use":"Часы на входе — разбивка оплаты: обычная, сверхурочная, двойная и итог.","tool.heart-rate-zone-calc.name":"Калькулятор пульсовых зон","tool.heart-rate-zone-calc.use":"Возраст и пульс покоя на входе — пять зон и эффект каждой на выходе.","tool.car-payment-calc.name":"Калькулятор автокредита","tool.car-payment-calc.use":"От цены в прайсе до реального платежа, с налогом и сборами дилера.","tool.apr-apy-calc.name":"Калькулятор APR в APY","tool.apr-apy-calc.use":"APR и APY расходятся лишь по одной причине — как часто начисляются сложные проценты.","tool.btu-calc.name":"Калькулятор BTU","tool.btu-calc.use":"Площадь задаёт базу, а солнце, высота потолка и люди её сдвигают. Слишком мощный кондиционер оставляет комнату холодной и сырой.","tool.concrete-calc.name":"Калькулятор бетона","tool.concrete-calc.use":"Плита, фундамент или колонна — введите размеры и получите ярды, кубометры и число мешков с запасом на потери.","tool.csv-diff.name":"Csv Diff","tool.csv-diff.use":"Посмотрите, что добавлено, удалено и изменено между двумя CSV — прямо в браузере, ничего не загружается.","tool.dividend-calc.name":"Dividend Calculator","tool.dividend-calc.use":"Есть дивидендная акция или ETF? Введите количество акций, цену и дивиденд — за секунды увидите доходность и годовой доход, затем включите реинвестирование, чтобы спрогнозировать, как DRIP наращивает портфель годами, уже с учётом налога и инфляции. Работает в любой валюте.","tool.paint-calc.name":"Калькулятор краски","tool.paint-calc.use":"Вводите размеры комнаты — получаете расход. Двери, окна и второй слой уже учтены.","tool.rent-affordability-calc.name":"Калькулятор доступной аренды","tool.rent-affordability-calc.use":"Правило 30%, проверка «40 аренд» у арендодателя и то, что реально остаётся после кредитов.","tool.tile-calc.name":"Калькулятор плитки","tool.tile-calc.use":"Размер помещения, формат плитки и запас на подрезку — эти три числа решают, сколько вы увезёте из магазина.","tool.utm-builder.name":"Массовый UTM-конструктор","tool.utm-builder.use":"Вставьте списки значений один раз — получите каждую размеченную ссылку кампании, проверенную по правилам GA4.","tool.vehicle-log-agg.name":"Агрегатор путевых журналов служебных автомоб","tool.vehicle-log-agg.use":"Превратите тысячи строк поездок по всем служебным автомобилям в долю служебного использования и вычитаемую сумму — полностью в вашем браузере.","tool.wbs-progress-rollup.name":"Взвешенный прогресс по СДР и сводка EVM","tool.wbs-progress-rollup.use":"Вставьте СДР. Веса поднимаются по иерархии, отстающие задачи всплывают, таблица для еженедельного отчёта копируется.","tool.workback-schedule.name":"Конструктор обратного графика","tool.workback-schedule.use":"Задайте дедлайн, вставьте задачи. Мы отсчитываем назад в рабочих днях и говорим, не опаздываете ли вы уже.","tool.home-affordability-calc.name":"Калькулятор доступности жилья","tool.home-affordability-calc.use":"Банк называет потолок. Здесь виден и потолок, и цена, с которой реально комфортно жить.","tool.json-diff.name":"JSON Diff","tool.json-diff.use":"Вставьте два документа JSON — каждое различие вернётся с полным путём.","tool.password-strength-checker.name":"Проверка надёжности пароля","tool.password-strength-checker.use":"Сколько битов энтропии на самом деле в вашем пароле и сколько времени займёт настоящая атака?","tool.paycheck-calc.name":"Калькулятор зарплаты в США","tool.paycheck-calc.use":"Смотрите, сколько реально приходит на счёт: федеральная шкала 2025 года, FICA и ставка вашего штата.","tool.zakat-calc.name":"Калькулятор закята","tool.zakat-calc.use":"Сложите имущество, вычтите долги к оплате сейчас, сравните с нисабом. Дальше — 2,5%.","tool.a1c-calc.name":"Калькулятор HbA1c","tool.a1c-calc.use":"Ваш HbA1c в единицах глюкометра и его место на шкале ADA.","tool.board-foot-calc.name":"Калькулятор борд-футов","tool.board-foot-calc.use":"Толщина в четвертях, ширина в дюймах, длина в футах — та самая цифра, по которой выставляют счёт.","tool.bra-size-calc.name":"Калькулятор размера бюстгальтера","tool.bra-size-calc.use":"Два измерения дают размеры США, Великобритании и ЕС, а также сестринские размеры, когда посадка почти идеальна.","tool.car-lease-calc.name":"Калькулятор автолизинга","tool.car-lease-calc.use":"Лизинг держится на двух числах: сколько теряет машина и сколько стоят деньги.","tool.gravel-calc.name":"Калькулятор щебня","tool.gravel-calc.use":"Кубические ярды, тонны и запас на уплотнение для подъездов, площадок, дорожек и дренажа.","tool.heat-index-calc.name":"Калькулятор индекса жары","tool.heat-index-calc.use":"32°C при влажности 70% ощущаются как 40°C. Опасность определяет влажность, а не термометр.","tool.mpg-calc.name":"Калькулятор расхода топлива","tool.mpg-calc.use":"Двух цифр с последней заправки хватает, чтобы узнать реальный расход.","tool.mulch-calc.name":"Калькулятор мульчи","tool.mulch-calc.use":"Вводите размеры клумбы и толщину слоя — получаете кубические ярды и число мешков ещё до поездки в садовый центр.","tool.number-to-words.name":"Число прописью по-английски","tool.number-to-words.use":"Введите число — получите слова, включая точную формулировку, которую банк ждёт на чеке.","tool.pool-volume-calc.name":"Калькулятор объёма бассейна","tool.pool-volume-calc.use":"Длина, ширина, глубина — и вы точно знаете, сколько хлора, соли или шоковой дозы нужно воде.","tool.readability-checker.name":"Проверка читабельности","tool.readability-checker.use":"Вставьте текст и посмотрите индекс Флеша, уровень чтения и статистику предложений, которая за ними стоит.","tool.wind-chill-calc.name":"Калькулятор ветрового охлаждения","tool.wind-chill-calc.use":"Ветер срывает с кожи тонкий слой согретого воздуха. Узнайте, как холод ощущается на самом деле.","tool.age-gap-calc.name":"Калькулятор разницы в возрасте между двумя д","tool.age-gap-calc.use":"Точные годы, месяцы и дни между двумя днями рождения — и старое правило «половина плюс семь».","tool.density-calc.name":"Калькулятор плотности","tool.density-calc.use":"Плотность = масса ÷ объём. Введите два значения — третье вернётся во всех привычных единицах.","tool.fence-calc.name":"Калькулятор забора","tool.fence-calc.use":"Замерьте линию забора один раз — и получите полный список материалов: столбы, лаги, штакетник и стоимость.","tool.golf-handicap-calc.name":"Калькулятор гандикапа в гольфе","tool.golf-handicap-calc.use":"Введите последние раунды — калькулятор применит формулу дифференциалов WHS и поправку при малом числе карточек.","tool.half-life-calc.name":"Калькулятор периода полураспада и полувыведе","tool.half-life-calc.use":"Одна формула описывает кофеин, углерод-14 и выведение лекарства. Введите известные величины — остальное посчитается.","tool.molar-mass-calc.name":"Калькулятор молярной массы","tool.molar-mass-calc.use":"Введите формулу вроде Ca(OH)2 или CuSO4.5H2O и получите граммы на моль вместе с полным составом по массе.","tool.ohms-law-calc.name":"Калькулятор закона Ома","tool.ohms-law-calc.use":"Заполните два поля. Остальные два — это алгебра, и инструмент покажет ход расчёта.","tool.resistor-color-code.name":"Калькулятор цветовой маркировки резисторов","tool.resistor-color-code.use":"Выберите полосы — получите значение. Резисторы на четыре и пять колец вместе с диапазоном допуска.","tool.sig-fig-calc.name":"Калькулятор значащих цифр","tool.sig-fig-calc.use":"Видно, какие именно цифры значащие, и можно округлить до любого их количества.","tool.stair-calc.name":"Калькулятор лестницы","tool.stair-calc.use":"Введите высоту от пола до пола — получите равные подступенки, длину марша и тетиву по нормам.","tool.tank-volume-calc.name":"Калькулятор объёма ёмкости","tool.tank-volume-calc.use":"Объём цилиндрических и прямоугольных ёмкостей в галлонах — и сколько на самом деле налито при заданном уровне.","tool.words-to-pages.name":"Слова в страницы","tool.words-to-pages.use":"Сколько страниц в 1500 словах? Решают шрифт и интервал — выберите оба и получите реальный объём.","tool.drywall-calc.name":"Калькулятор гипсокартона","tool.drywall-calc.use":"Вводите размеры комнаты — получаете список материалов: листы, шпаклёвка, лента и саморезы с учётом запаса.","tool.pregnancy-weight-gain-calc.name":"Калькулятор набора веса при беременности (IO","tool.pregnancy-weight-gain-calc.use":"Целевой диапазон зависит от ИМТ до беременности — одной цифры для всех не существует.","tool.roof-pitch-calc.name":"Калькулятор уклона крыши","tool.roof-pitch-calc.use":"Один замер — сразу всё: уклон x/12, градусы, проценты и длина стропила.","tool.rule-of-72-calc.name":"Правило 72","tool.rule-of-72-calc.use":"Разделите 72 на годовую доходность — срок удвоения получается устно, без таблиц.","tool.sand-calc.name":"Калькулятор песка","tool.sand-calc.use":"Длина, ширина и толщина слоя на входе — объём, вес и число мешков на выходе.","tool.topsoil-calc.name":"Калькулятор плодородного грунта","tool.topsoil-calc.use":"Объём задаёт толщина слоя, а не площадь. Десять сантиметров на маленькой клумбе — уже доставка навалом.","tool.wallpaper-calc.name":"Калькулятор обоев","tool.wallpaper-calc.use":"Рулоны, полотна и потери на раппорт — так, как считает мастер-обойщик.","tool.bsa-calc.name":"Калькулятор площади поверхности тела (BSA),","tool.bsa-calc.use":"Три опубликованные формулы площади поверхности тела рядом, в метрических или имперских единицах, плюс среднее значение.","tool.grass-seed-calc.name":"Калькулятор семян газона","tool.grass-seed-calc.use":"Посеете мало — придут сорняки, посеете густо — всходы задушат друг друга.","tool.http-status-lookup.name":"Коды состояния HTTP","tool.http-status-lookup.use":"Введите код — получите понятное объяснение и ответ, на чьей стороне проблема: клиента или сервера.","tool.json-to-yaml.name":"Конвертер JSON в YAML","tool.json-to-yaml.use":"Вставьте JSON и получите YAML, который примет даже строгий парсер — вместе с кавычками.","tool.ltv-calc.name":"Калькулятор LTV","tool.ltv-calc.use":"Показатель, по которому банк назначает ставку. Узнайте свой LTV, CLTV и где проходит граница 80%.","tool.net-worth-calc.name":"Калькулятор чистого капитала","tool.net-worth-calc.use":"Всё, чем вы владеете, минус всё, что вы должны. Одна честная цифра, которую проверяют раз в квартал.","tool.paver-calc.name":"Калькулятор тротуарной плитки","tool.paver-calc.use":"Размеры площадки и плитки на входе — количество, щебень, песок и стоимость на выходе.","tool.secret-santa-generator.name":"Генератор Тайного Санты","tool.secret-santa-generator.use":"Вставьте имена, нажмите жребий — браузер сам решит, кто кому дарит. Без регистрации, без почты и без того, чтобы кто-то вытянул сам себя.","tool.slug-generator.name":"Генератор URL-слагов","tool.slug-generator.use":"Вставьте заголовок и получите чистый адрес, понятный и поисковикам, и людям.","tool.smoking-cost-calc.name":"Калькулятор расходов на курение","tool.smoking-cost-calc.use":"У пачки в день есть цена. Вот она — вместе с суммой за десять лет.","tool.stamp-duty-calc.name":"Калькулятор гербового сбора","tool.stamp-duty-calc.use":"Действующие ступени SDLT для Англии и Северной Ирландии — разбивка по ступеням показывает, откуда берётся каждый фунт налога.","tool.stud-calc.name":"Калькулятор стоек","tool.stud-calc.use":"Длина стены, шаг, углы и проёмы — на выходе полный список 2x4 с запасом на подрезку.","tool.tire-size-calc.name":"Калькулятор размера шин","tool.tire-size-calc.use":"Введите 225/45R17 и 235/40R18 — увидите разницу диаметров, ошибку спидометра и укладывается ли замена в правило 3%.","tool.waist-hip-ratio-calc.name":"Калькулятор соотношения талии и бёдер (WHR)","tool.waist-hip-ratio-calc.use":"Где именно откладывается жир, важнее цифры на весах. Два замера сантиметром — один показатель.","tool.attendance-calc.name":"Калькулятор посещаемости","tool.attendance-calc.use":"Ваш процент, ваш запас и точное число занятий, которые можно пропустить.","tool.cgpa-to-percentage.name":"Перевод CGPA в проценты","tool.cgpa-to-percentage.use":"Умножение на 9,5 — правило одного экзаменационного совета, а не универсальный закон. Берите коэффициент своего вуза.","tool.download-time-calc.name":"Калькулятор времени загрузки файла","tool.download-time-calc.use":"Провайдер продаёт биты, а файлы измеряются в байтах. Именно на этой восьмёрке ошибается большинство расчётов.","tool.ev-charging-calc.name":"Калькулятор времени зарядки электромобиля","tool.ev-charging-calc.use":"Ёмкость батареи, мощность станции и реалистичный КПД — три числа, которые определяют время зарядки.","tool.gold-purity-calc.name":"Калькулятор пробы золота","tool.gold-purity-calc.use":"22 карата — это 91,67 % золота. Посчитайте, сколько металла у вас на самом деле.","tool.gratuity-calc.name":"Калькулятор gratuity (Индия)","tool.gratuity-calc.use":"Базовый оклад + DA, стаж и формула 15/26 — с правилом пяти лет и потолком в ₹20 лакхов.","tool.marks-percentage-calc.name":"Калькулятор процента баллов","tool.marks-percentage-calc.use":"Укажите баллы и максимум по каждому предмету. Получите общий процент с двумя знаками после запятой, разбивку и диапазон оценки.","tool.nap-calc.name":"Калькулятор дневного сна","tool.nap-calc.use":"Двадцать минут — и вы бодры. Шестьдесят — и вы разбиты. Вот время будильника для сна, который вы собираетесь начать.","tool.ppi-calc.name":"Калькулятор PPI","tool.ppi-calc.use":"Введите разрешение и размер экрана. Получите плотность пикселей, размер зерна и расстояние, с которого отдельные пиксели перестают быть видны.","tool.sip-calc.name":"SIP-калькулятор","tool.sip-calc.use":"Посмотрите, сколько будет стоить ваш ежемесячный взнос в фонд к концу срока и какая часть суммы — это сложный процент, а не ваши деньги.","tool.torque-conv.name":"Конвертер крутящего момента","tool.torque-conv.use":"Одно значение — четыре единицы момента, ещё до настройки динамометрического ключа.","tool.wedding-budget-calc.name":"Калькулятор бюджета свадьбы","tool.wedding-budget-calc.use":"Введите общую сумму и число гостей — получите разбивку, которой пользуются организаторы.","tool.cholesterol-ratio-calc.name":"Калькулятор коэффициента холестерина","tool.cholesterol-ratio-calc.use":"Один липидный профиль — четыре числа. Коэффициенты возвращают ЛПВП в расчёт: везде чем ниже, тем лучше.","tool.coffee-ratio-calc.name":"Калькулятор пропорции кофе и воды","tool.coffee-ratio-calc.use":"Введите объём воды и получите навеску кофе — или наоборот, для любого способа заваривания.","tool.hra-calc.name":"Калькулятор HRA","tool.hra-calc.use":"Освобождается наименьшая из трёх величин. Здесь видно, какая из них ограничивает.","tool.ppf-calc.name":"Калькулятор PPF","tool.ppf-calc.use":"Пятнадцать лет и освобождение от налога на каждом этапе. Посмотрите, во что превращается ежегодный взнос.","tool.px-to-rem.name":"Конвертер px в rem","tool.px-to-rem.use":"Введите значение в пикселях — получите rem и строку CSS для вставки.","tool.rd-calc.name":"Калькулятор RD","tool.rd-calc.use":"Каждый взнос работает разное количество месяцев. Калькулятор складывает их по одному.","tool.rent-split-calc.name":"Калькулятор раздела аренды","tool.rent-split-calc.use":"Комнаты разные, доходы разные — договоритесь, кто сколько платит, до подписания договора.","tool.robots-txt-generator.name":"Генератор robots.txt","tool.robots-txt-generator.use":"Пресеты для типовых случаев, свои правила для остального и проверка перед загрузкой на сервер.","tool.salary-hike-calc.name":"Калькулятор повышения зарплаты","tool.salary-hike-calc.use":"В обе стороны: процент из двух окладов или новый оклад из процента.","tool.sod-calc.name":"Калькулятор рулонного газона","tool.sod-calc.use":"Измерьте один раз, добавьте запас на подрезку и закажите нужное число рулонов или поддонов сразу.","tool.sunrise-sunset-calc.name":"Калькулятор восхода и заката","tool.sunrise-sunset-calc.use":"Солнечная геометрия NOAA для любой точки Земли — восход, закат, сумерки и долгота дня прямо в браузере.","tool.word-frequency-counter.name":"Частотный анализ слов","tool.word-frequency-counter.use":"Вставьте текст и увидите, на какие слова вы действительно опираетесь — с процентами, а не на глазок.","tool.asphalt-calc.name":"Калькулятор асфальта","tool.asphalt-calc.use":"Сколько нужно асфальта? Тоннаж, объём и стоимость материала по длине, ширине и толщине после уплотнения.","tool.brick-calc.name":"Калькулятор кирпича","tool.brick-calc.use":"Вводите размеры стены — получаете количество кирпича вместе со швом и запасом на бой.","tool.car-affordability-calc.name":"Калькулятор доступности автомобиля","tool.car-affordability-calc.use":"Три правила без участия продавца и один честный ответ — до визита в автосалон.","tool.cd-calc.name":"Калькулятор вклада CD","tool.cd-calc.use":"CD котируются в APY, значит капитализация уже в ставке. Здесь видно, во что это превращается в деньгах.","tool.decking-calc.name":"Калькулятор террасной доски","tool.decking-calc.use":"Вводите размеры террасы — получаете количество досок вместе с зазором, запасом на подрезку и крепежом.","tool.generator-size-calc.name":"Калькулятор мощности генератора","tool.generator-size-calc.use":"Отметьте то, что должно продолжать работать. Складываем ватты и добавляем самый тяжёлый пуск одного мотора.","tool.lbm-calc.name":"Калькулятор сухой массы тела","tool.lbm-calc.use":"Всё, из чего вы состоите, кроме жира: три опубликованные формулы и прямой расчёт по проценту жира.","tool.rebar-calc.name":"Калькулятор арматуры","tool.rebar-calc.use":"Введите размеры плиты и шаг сетки — получите раскладку, общую длину и число хлыстов к заказу.","tool.refinance-calc.name":"Калькулятор рефинансирования","tool.refinance-calc.use":"Меньший платёж — не то же самое, что меньшая стоимость. Точка окупаемости и общие проценты рядом.","tool.shingle-calc.name":"Калькулятор гибкой черепицы","tool.shingle-calc.use":"Габариты дома, уклон и запас превращаются в пачки, квадраты, подкладку и гвозди.","tool.solar-panel-calc.name":"Калькулятор солнечных панелей","tool.solar-panel-calc.use":"Киловатт-часы из счёта, ваши солнечные часы и крыша — количество панелей за один шаг.","tool.vo2max-calc.name":"Калькулятор МПК (VO2 max)","tool.vo2max-calc.use":"Три полевых теста, один аэробный потолок — и честная оценка вашего уровня.","tool.annuity-calc.name":"Калькулятор аннуитета","tool.annuity-calc.use":"Три вопроса, одна формула: сколько в месяц, на сколько хватит, сколько нужно.","tool.ascii-table.name":"Таблица ASCII","tool.ascii-table.use":"Введите символ или код — получите все представления сразу; полная таблица 0-127 ниже.","tool.budget-calc.name":"Калькулятор бюджета 50/30/20 на месяц","tool.budget-calc.use":"Введите одну сумму — и увидите, сколько в этом месяце уходит на нужды, желания и накопления.","tool.freelance-rate-calc.name":"Калькулятор ставки фрилансера","tool.freelance-rate-calc.use":"Ставка ниже этой означает, что вы доплачиваете за право работать на себя.","tool.meeting-cost-calc.name":"Калькулятор стоимости совещания","tool.meeting-cost-calc.use":"Каждое приглашение в календаре — это заявка на закупку. Вот ценник до отправки.","tool.plant-spacing-calc.name":"Калькулятор расстояния между растениями","tool.plant-spacing-calc.use":"Введите размеры грядки и расстояние с этикетки — узнаете количество ещё до покупки.","tool.prorated-rent-calc.name":"Калькулятор аренды за неполный месяц","tool.prorated-rent-calc.use":"Заезжаете в середине месяца? Узнайте точную сумму и разницу между тремя стандартными способами.","tool.race-time-predictor.name":"Калькулятор прогноза времени забега","tool.race-time-predictor.use":"Один недавний старт превращается в реалистичное время на любой другой дистанции.","tool.tv-size-calc.name":"Калькулятор размера телевизора и расстояния","tool.tv-size-calc.use":"Размер экрана — это на самом деле вопрос угла обзора. Укажите расстояние до дивана, остальное посчитается.","tool.url-parser.name":"Парсер URL","tool.url-parser.use":"Ссылка — это маленькая запись с полями. Вставьте её и прочитайте каждое поле.","tool.cap-rate-calc.name":"Калькулятор ставки капитализации (cap rate)","tool.cap-rate-calc.use":"Cap rate — доходность самого объекта без кредита: цена, аренда и реальные операционные расходы.","tool.carpet-calc.name":"Калькулятор ковролина","tool.carpet-calc.use":"Ковролин режут из рулона, а не по форме комнаты. Ширина рулона задаёт швы и большую часть отходов.","tool.emergency-fund-calc.name":"Калькулятор подушки безопасности","tool.emergency-fund-calc.use":"Три месяца или шесть? Размер подушки считают от обязательных расходов, а не от зарплаты до вычетов.","tool.furnace-size-calc.name":"Расчёт мощности отопления в BTU","tool.furnace-size-calc.use":"Одной площади мало: климатическая зона меняет нужную мощность почти вдвое.","tool.laminate-flooring-calc.name":"Калькулятор ламината","tool.laminate-flooring-calc.use":"Введите размеры комнаты и площадь упаковки с этикетки — получите точное число упаковок.","tool.matrix-calc.name":"Калькулятор матриц","tool.matrix-calc.use":"Шесть операций, два размера и показанный ход решения, а не только ответ.","tool.npv-irr-calc.name":"Калькулятор NPV и IRR","tool.npv-irr-calc.use":"Введите денежные потоки проекта и посмотрите, создаёт ли он ценность при вашей ставке.","tool.party-drink-calc.name":"Калькулятор напитков для вечеринки","tool.party-drink-calc.use":"Два напитка в первый час и по одному каждый следующий — с пересчётом на список гостей.","tool.permutation-combination-calc.name":"Калькулятор сочетаний","tool.permutation-combination-calc.use":"Важен ли порядок? Ответьте на это — остальное просто арифметика.","tool.retaining-wall-calc.name":"Калькулятор подпорной стены","tool.retaining-wall-calc.use":"Количество блоков, заглублённый первый ряд и дренажный щебень, от которого зависит, будет ли стена ровной через десять лет.","tool.water-heater-size-calc.name":"Калькулятор объёма водонагревателя","tool.water-heater-size-calc.use":"Считайте по самому загруженному часу, а не на глаз — бак или проточный.","tool.z-score-calc.name":"Калькулятор Z-оценки","tool.z-score-calc.use":"На сколько стандартных отклонений вы отстоите от среднего и какому процентилю это соответствует.","tool.army-body-fat-calc.name":"Калькулятор жира армии США","tool.army-body-fat-calc.use":"Один замер живота на уровне пупка плюс рост — сверка с нормативом AR 600-9 для вашей возрастной группы.","tool.commission-calc.name":"Калькулятор комиссии","tool.commission-calc.use":"Одна сделка, три схемы комиссии — посмотрите, сколько реально платит план.","tool.commute-cost-calc.name":"Калькулятор стоимости поездок на работу","tool.commute-cost-calc.use":"Бензин — меньшая часть счёта. Остальное это амортизация, страховка и парковка.","tool.insulation-calc.name":"Калькулятор утеплителя","tool.insulation-calc.use":"Задайте целевое значение R — получите толщину слоя и количество мешков или пачек: чердак, стены, перекрытия.","tool.markdown-table-generator.name":"Генератор таблиц Markdown","tool.markdown-table-generator.use":"Заполните сетку и скопируйте разметку. Двоеточия выравнивания и отступы — на нас.","tool.percent-error-calc.name":"Калькулятор относительной погрешности","tool.percent-error-calc.use":"Насколько ваше измерение отличается от истинного значения — в процентах и с направлением.","tool.position-size-calc.name":"Калькулятор размера позиции","tool.position-size-calc.use":"Стоп задаёт риск на одну акцию, а счёт — цену, которую вы готовы заплатить за ошибку.","tool.recipe-scaler.name":"Пересчёт рецепта","tool.recipe-scaler.use":"Половина, двойная порция или ровно на семерых — дроби посчитает инструмент.","tool.siding-calc.name":"Калькулятор сайдинга","tool.siding-calc.use":"Введите периметр, высоту стены и фронтоны — получите площадь, коробки и метраж доборов.","tool.wilks-calc.name":"Калькулятор Уилкса","tool.wilks-calc.use":"Одна сумма — две системы коэффициентов: сегодня большинство федераций ранжирует по DOTS.","tool.biweekly-mortgage-calc.name":"Калькулятор платежей раз в две недели по ипо","tool.biweekly-mortgage-calc.use":"Половина платежа каждые две недели даёт 13 месячных платежей в год. Вот что приносит этот тринадцатый.","tool.caffeine-calc.name":"Калькулятор кофеина","tool.caffeine-calc.use":"Посчитайте кофеин за день, сравните с пределом 400 мг и узнайте, сколько его останется в организме, когда вы ляжете спать.","tool.dilution-calc.name":"Калькулятор разведения","tool.dilution-calc.use":"Объём исходного раствора, сколько растворителя добавить и кратность разведения — с готовой формулировкой для лабораторного журнала.","tool.grout-calc.name":"Калькулятор затирки","tool.grout-calc.use":"Всё решают размер плитки и ширина шва: мелкая плитка съедает в шесть раз больше затирки.","tool.kinetic-energy-calc.name":"Калькулятор кинетической энергии","tool.kinetic-energy-calc.use":"Скорость вдвое больше — энергия вчетверо. В этом вся история тормозного пути.","tool.mileage-reimbursement-calc.name":"Калькулятор компенсации за пробег","tool.mileage-reimbursement-calc.use":"Введите мили, выберите ставку — получите сумму для авансового отчёта.","tool.propane-calc.name":"Калькулятор газового баллона","tool.propane-calc.use":"Полный баллон на 20 фунтов содержит около 430 000 BTU. Как быстро это уйдёт, решает ваша горелка.","tool.ramp-calc.name":"Калькулятор пандуса для коляски","tool.ramp-calc.use":"Введите высоту — получите длину пандуса, уклон в градусах, площадки и правило по поручням.","tool.self-employment-tax-calc.name":"Калькулятор налога на самозанятость (SE tax)","tool.self-employment-tax-calc.use":"Доход фрилансера облагается дважды: сначала SE tax, затем подоходный налог сверху. Здесь считаем SE tax.","tool.wavelength-calc.name":"Калькулятор длины волны и частоты","tool.wavelength-calc.use":"Одно значение — и сразу всё: длина волны, частота, энергия фотона и место на спектре.","cat.science":"Математика и наука","ux.share":"Поделиться инструментом","ux.example":"Попробовать пример","ux.copyHint":"Нажмите, чтобы скопировать","ux.copied":"Скопировано","tools.recent":"Недавние","sources.heading":"Источники и дополнительные материалы"};
